const n=[{id:"vb14-1",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 3",gt:"Độ tuổi lao động tối thiểu là đủ 15 tuổi, trừ trường hợp lao động chưa thành niên theo quy định riêng.",mn:'"Đủ 15 tuổi mới được làm việc".',t:"m",q:"Theo Bộ Luật Lao động, độ tuổi lao động tối thiểu của người lao động được xác định là bao nhiêu, trừ một số trường hợp đặc biệt đối với người chưa thành niên?",o:["Đủ 15 tuổi","Đủ 14 tuổi","Đủ 16 tuổi","Đủ 18 tuổi"],c:0},{id:"vb14-2",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 3",gt:"Người lao động gắn với 3 dấu hiệu: có thỏa thuận, được trả lương và chịu sự quản lý, điều hành, giám sát.",mn:'"Trả lương + chịu quản lý = người lao động".',t:"m",q:"Theo Bộ Luật Lao động, người làm việc cho người sử dụng lao động theo thỏa thuận, được trả lương và chịu sự quản lý, điều hành, giám sát của người sử dụng lao động được gọi là gì?",o:["Người tập nghề","Người lao động","Người làm việc không có quan hệ lao động","Người học nghề"],c:1},{id:"vb14-3",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 3",gt:"Người sử dụng lao động là cá nhân phải có năng lực hành vi dân sự đầy đủ.",mn:'"Cá nhân thuê lao động phải có năng lực hành vi dân sự đầy đủ".',t:"m",q:"Theo Bộ Luật Lao động, trường hợp người sử dụng lao động là cá nhân thì cá nhân đó phải đáp ứng điều kiện nào sau đây?",o:["Đủ 15 tuổi trở lên","Có giấy phép kinh doanh","Có năng lực hành vi dân sự đầy đủ","Đã đăng ký hộ kinh doanh"],c:2},{id:"vb14-4",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 3",gt:"Cưỡng bức lao động = dùng vũ lực, đe dọa dùng vũ lực hoặc thủ đoạn khác ép buộc làm việc trái ý muốn.",mn:'"Ép làm trái ý muốn = cưỡng bức lao động".',t:"m",q:"Theo Bộ Luật Lao động, việc dùng vũ lực, đe dọa dùng vũ lực hoặc các thủ đoạn khác để ép buộc người lao động phải làm việc trái ý muốn của họ được gọi là gì?",o:["Ngược đãi người lao động","Phân biệt đối xử trong lao động","Quấy rối tại nơi làm việc","Cưỡng bức lao động"],c:3},{id:"vb14-5",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 3",gt:"Quan hệ lao động gồm quan hệ lao động cá nhân và quan hệ lao động tập thể.",mn:'"Cá nhân + tập thể".',t:"m",q:"Theo Bộ Luật Lao động, quan hệ lao động bao gồm những loại quan hệ nào sau đây?",o:["Quan hệ lao động cá nhân và quan hệ lao động tập thể","Quan hệ lao động chính thức và không chính thức","Quan hệ lao động trong nước và ngoài nước","Quan hệ lao động dài hạn và ngắn hạn"],c:0},{id:"vb14-6",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 3",gt:"Tổ chức đại diện người lao động tại cơ sở gồm công đoàn cơ sở và tổ chức của người lao động tại doanh nghiệp.",mn:'"Công đoàn cơ sở + tổ chức của NLĐ tại DN".',t:"m",q:"Theo Bộ Luật Lao động, tổ chức đại diện người lao động tại cơ sở bao gồm những thành phần nào?",o:["Công đoàn cấp trên và công đoàn cơ sở","Công đoàn cơ sở và tổ chức của người lao động tại doanh nghiệp","Ban chấp hành công đoàn và hội đồng người lao động","Tổ chức nghề nghiệp và công đoàn cơ sở"],c:1},{id:"vb14-7",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 3",gt:"Người làm việc không có quan hệ lao động = làm việc không dựa trên thuê mướn bằng hợp đồng lao động.",mn:'"Không hợp đồng lao động = không có quan hệ lao động".',t:"m",q:"Theo Bộ Luật Lao động, người làm việc không trên cơ sở thuê mướn bằng hợp đồng lao động được gọi là gì?",o:["Người lao động tự do","Người lao động thời vụ","Người làm việc không có quan hệ lao động","Người tập nghề"],c:2},{id:"vb14-8",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 3",gt:"Quấy rối tình dục tại nơi làm việc = hành vi tính chất tình dục không được người khác mong muốn hoặc chấp nhận.",mn:'"Không mong muốn, không chấp nhận = quấy rối".',t:"m",q:"Theo Bộ Luật Lao động, hành vi có tính chất tình dục của bất kỳ người nào đối với người khác tại nơi làm việc mà không được người đó mong muốn hoặc chấp nhận được gọi là gì?",o:["Ngược đãi người lao động","Cưỡng bức lao động","Phân biệt đối xử trong lao động","Quấy rối tình dục tại nơi làm việc"],c:3},{id:"vb14-9",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 2",gt:"Đối tượng áp dụng gồm người lao động, người sử dụng lao động, lao động nước ngoài và cơ quan, tổ chức, cá nhân có liên quan trực tiếp đến quan hệ lao động.",mn:'"Phải liên quan trực tiếp đến quan hệ lao động".',t:"m",q:"Theo Bộ Luật Lao động, đối tượng nào sau đây KHÔNG thuộc đối tượng áp dụng của Bộ luật này?",o:["Tổ chức quốc tế không có liên quan đến quan hệ lao động","Người lao động, người học nghề, người tập nghề","Người sử dụng lao động","Người lao động nước ngoài làm việc tại Việt Nam"],c:0},{id:"vb14-10",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 8",gt:"Nghiêm cấm sử dụng lao động chưa thành niên trái pháp luật, phân biệt đối xử, ngược đãi, cưỡng bức và quấy rối.",mn:'"Cấm dùng lao động chưa thành niên trái luật".',t:"m",q:"Theo Bộ Luật Lao động, hành vi nào sau đây bị nghiêm cấm trong lĩnh vực lao động?",o:["Tuyển dụng lao động thông qua tổ chức dịch vụ việc làm","Sử dụng lao động chưa thành niên trái pháp luật","Đóng cửa tạm thời nơi làm việc","Bố trí, quản lý, điều hành lao động"],c:1},{id:"vb14-11",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 9",gt:"Việc làm = hoạt động lao động tạo ra thu nhập mà pháp luật không cấm.",mn:'"Tạo thu nhập + không bị cấm = việc làm".',t:"m",q:"Theo Bộ Luật Lao động, hoạt động lao động tạo ra thu nhập mà pháp luật không cấm được gọi là gì?",o:["Nghề nghiệp","Tuyển dụng lao động","Việc làm","Quan hệ lao động"],c:2},{id:"vb14-12",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 11",gt:"Người lao động không phải trả chi phí cho việc tuyển dụng lao động.",mn:'"Tuyển dụng: người lao động không mất phí".',t:"m",q:"Theo Bộ Luật Lao động, ai là người phải chịu chi phí cho việc tuyển dụng lao động?",o:["Người lao động","Tổ chức dịch vụ việc làm","Người lao động và người sử dụng lao động chia đôi","Người sử dụng lao động (người lao động không phải trả chi phí)"],c:3},{id:"vb14-13",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 12",gt:"Phải khai trình việc sử dụng lao động trong 30 ngày kể từ ngày bắt đầu hoạt động.",mn:'"Bắt đầu hoạt động: 30 ngày khai trình".',t:"m",q:"Theo Bộ Luật Lao động, người sử dụng lao động phải khai trình việc sử dụng lao động trong thời hạn bao nhiêu ngày kể từ ngày bắt đầu hoạt động?",o:["30 ngày","15 ngày","45 ngày","60 ngày"],c:0},{id:"vb14-14",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 12",gt:"Sổ quản lý lao động được lập bằng bản giấy hoặc bản điện tử và xuất trình khi cơ quan có thẩm quyền yêu cầu.",mn:'"Giấy hoặc điện tử đều được".',t:"m",q:"Theo Bộ Luật Lao động, sổ quản lý lao động do người sử dụng lao động lập được thể hiện dưới hình thức nào?",o:["Chỉ bằng bản giấy","Bản giấy hoặc bản điện tử","Chỉ bằng bản điện tử","Bản giấy có công chứng"],c:1},{id:"vb14-15",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 12",gt:"Báo cáo tình hình thay đổi lao động với cơ quan chuyên môn về lao động thuộc Ủy ban nhân dân cấp tỉnh và thông báo cơ quan bảo hiểm xã hội.",mn:'"Báo cáo lao động: cơ quan chuyên môn cấp tỉnh".',t:"m",q:"Theo Bộ Luật Lao động, người sử dụng lao động định kỳ báo cáo tình hình thay đổi về lao động với cơ quan nào?",o:["Cơ quan quản lý lao động cấp xã","Sở Nội vụ","Cơ quan chuyên môn về lao động thuộc Ủy ban nhân dân cấp tỉnh","Bộ Lao động - Thương binh và Xã hội"],c:2},{id:"vb14-16",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 13",gt:"Dù mang tên gọi khác, nếu có nội dung việc làm có trả công và có sự quản lý, điều hành, giám sát thì vẫn được coi là hợp đồng lao động.",mn:'"Có trả công + quản lý = hợp đồng lao động dù tên gì".',t:"m",q:"Theo Bộ Luật Lao động, trường hợp hai bên thỏa thuận bằng tên gọi khác nhưng nội dung thể hiện việc làm có trả công, tiền lương và sự quản lý, điều hành, giám sát của một bên thì được coi là gì?",o:["Hợp đồng dịch vụ","Hợp đồng đào tạo nghề","Hợp đồng cộng tác","Hợp đồng lao động"],c:3},{id:"vb14-17",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 14",gt:"Hợp đồng lao động bằng văn bản làm thành 02 bản, người lao động giữ 01 bản, người sử dụng lao động giữ 01 bản.",mn:'"Hai bản, mỗi bên một bản".',t:"m",q:"Theo Bộ Luật Lao động, hợp đồng lao động giao kết bằng văn bản được làm thành mấy bản và mỗi bên giữ bao nhiêu?",o:["02 bản, mỗi bên giữ 01 bản","03 bản, người lao động giữ 01 bản","02 bản, người sử dụng lao động giữ cả hai","01 bản do người sử dụng lao động giữ"],c:0},{id:"vb14-18",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 14",gt:"Chỉ được giao kết bằng lời nói với hợp đồng có thời hạn dưới 01 tháng (trừ một số trường hợp phải bằng văn bản).",mn:'"Dưới 1 tháng mới được nói miệng".',t:"m",q:"Theo Bộ Luật Lao động, hai bên có thể giao kết hợp đồng lao động bằng lời nói đối với hợp đồng có thời hạn như thế nào?",o:["Dưới 03 tháng","Dưới 01 tháng","Dưới 12 tháng","Dưới 06 tháng"],c:1},{id:"vb14-19",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 20",gt:"Hợp đồng lao động xác định thời hạn có thời gian không quá 36 tháng kể từ thời điểm có hiệu lực.",mn:'"Xác định thời hạn tối đa 36 tháng".',t:"m",q:"Theo Bộ Luật Lao động, hợp đồng lao động xác định thời hạn là hợp đồng mà hai bên xác định thời hạn, thời điểm chấm dứt trong thời gian tối đa là bao lâu?",o:["Không quá 24 tháng","Không quá 12 tháng","Không quá 36 tháng","Không quá 48 tháng"],c:2},{id:"vb14-20",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 20",gt:"Trong 30 ngày kể từ ngày hết hạn, hai bên phải ký hợp đồng lao động mới; nếu không ký thì hợp đồng cũ trở thành không xác định thời hạn.",mn:'"Hết hạn: 30 ngày ký mới".',t:"m",q:"Theo Bộ Luật Lao động, khi hợp đồng lao động xác định thời hạn hết hạn mà người lao động vẫn tiếp tục làm việc thì trong thời hạn bao nhiêu ngày hai bên phải ký kết hợp đồng lao động mới?",o:["15 ngày","45 ngày","60 ngày","30 ngày"],c:3},{id:"vb14-21",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 20",gt:"Chỉ được ký thêm hợp đồng xác định thời hạn 01 lần, sau đó nếu tiếp tục làm việc thì phải ký hợp đồng không xác định thời hạn.",mn:'"Xác định thời hạn: chỉ gia hạn 1 lần".',t:"m",q:"Theo Bộ Luật Lao động, đối với hợp đồng lao động xác định thời hạn, sau khi hết hạn hai bên được ký kết thêm hợp đồng xác định thời hạn tối đa bao nhiêu lần?",o:["Chỉ 01 lần","02 lần","03 lần","Không giới hạn số lần"],c:0},{id:"vb14-22",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 25",gt:"Thử việc với người quản lý doanh nghiệp tối đa 180 ngày.",mn:'"Quản lý doanh nghiệp: 180 ngày".',t:"m",q:"Theo Bộ Luật Lao động, thời gian thử việc tối đa đối với công việc của người quản lý doanh nghiệp là bao nhiêu?",o:["Không quá 60 ngày","Không quá 180 ngày","Không quá 90 ngày","Không quá 30 ngày"],c:1},{id:"vb14-23",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 25",gt:"Thử việc với công việc cần trình độ cao đẳng trở lên tối đa 60 ngày.",mn:'"Cao đẳng trở lên: 60 ngày".',t:"m",q:"Theo Bộ Luật Lao động, thời gian thử việc tối đa đối với công việc có chức danh nghề nghiệp cần trình độ chuyên môn, kỹ thuật từ cao đẳng trở lên là bao nhiêu?",o:["Không quá 30 ngày","Không quá 90 ngày","Không quá 60 ngày","Không quá 180 ngày"],c:2},{id:"vb14-24",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 25",gt:"Thử việc với công việc cần trình độ trung cấp, công nhân kỹ thuật, nhân viên nghiệp vụ tối đa 30 ngày.",mn:'"Trung cấp: 30 ngày".',t:"m",q:"Theo Bộ Luật Lao động, thời gian thử việc tối đa đối với công việc cần trình độ trung cấp, công nhân kỹ thuật, nhân viên nghiệp vụ là bao nhiêu?",o:["Không quá 60 ngày","Không quá 06 ngày làm việc","Không quá 90 ngày","Không quá 30 ngày"],c:3},{id:"vb14-25",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 25",gt:"Thử việc với công việc khác tối đa 06 ngày làm việc.",mn:'"Việc khác: 6 ngày làm việc".',t:"m",q:"Theo Bộ Luật Lao động, thời gian thử việc tối đa đối với công việc khác (không thuộc các nhóm còn lại) là bao nhiêu?",o:["Không quá 06 ngày làm việc","Không quá 30 ngày","Không quá 15 ngày","Không quá 03 ngày làm việc"],c:0},{id:"vb14-26",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 26",gt:"Tiền lương thử việc ít nhất bằng 85% mức lương của công việc đó.",mn:'"Thử việc lương tối thiểu 85%".',t:"m",q:"Theo Bộ Luật Lao động, tiền lương của người lao động trong thời gian thử việc do hai bên thỏa thuận nhưng ít nhất phải bằng bao nhiêu mức lương của công việc đó?",o:["80%","85%","75%","70%"],c:1},{id:"vb14-27",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 24",gt:"Không áp dụng thử việc với hợp đồng lao động có thời hạn dưới 01 tháng.",mn:'"Dưới 1 tháng: không thử việc".',t:"m",q:"Theo Bộ Luật Lao động, đối với hợp đồng lao động nào sau đây thì KHÔNG áp dụng thử việc?",o:["Hợp đồng lao động xác định thời hạn 12 tháng","Hợp đồng lao động không xác định thời hạn","Hợp đồng lao động có thời hạn dưới 01 tháng","Hợp đồng lao động có thời hạn 06 tháng"],c:2},{id:"vb14-28",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 29",gt:"Được tạm thời chuyển công việc khác nhưng không quá 60 ngày làm việc cộng dồn trong 01 năm; quá thời hạn này phải có văn bản đồng ý của người lao động.",mn:'"Chuyển việc tạm: 60 ngày/năm".',t:"m",q:"Theo Bộ Luật Lao động, khi gặp khó khăn đột xuất do thiên tai, hỏa hoạn hoặc do nhu cầu sản xuất, kinh doanh, người sử dụng lao động được tạm thời chuyển người lao động làm công việc khác tối đa bao nhiêu ngày làm việc cộng dồn trong 01 năm (nếu không có văn bản đồng ý)?",o:["90 ngày làm việc","30 ngày làm việc","45 ngày làm việc","60 ngày làm việc"],c:3},{id:"vb14-29",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 29",gt:"Phải báo trước ít nhất 03 ngày làm việc, thông báo rõ thời hạn và bố trí công việc phù hợp.",mn:'"Chuyển việc phải báo trước 3 ngày làm việc".',t:"m",q:"Theo Bộ Luật Lao động, khi tạm thời chuyển người lao động làm công việc khác so với hợp đồng, người sử dụng lao động phải báo trước cho người lao động ít nhất bao nhiêu?",o:["03 ngày làm việc","05 ngày làm việc","07 ngày làm việc","01 ngày làm việc"],c:0},{id:"vb14-30",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 29",gt:"Được giữ nguyên tiền lương công việc cũ trong 30 ngày làm việc; sau đó lương công việc mới ít nhất bằng 85% lương cũ.",mn:'"Giữ lương cũ 30 ngày làm việc".',t:"m",q:"Theo Bộ Luật Lao động, khi chuyển sang làm công việc mới có tiền lương thấp hơn, người lao động được giữ nguyên tiền lương của công việc cũ trong thời hạn bao lâu?",o:["15 ngày làm việc","30 ngày làm việc","60 ngày làm việc","45 ngày làm việc"],c:1},{id:"vb14-31",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 31",gt:"Trong 15 ngày kể từ ngày hết thời hạn tạm hoãn, người lao động phải có mặt và người sử dụng lao động phải nhận trở lại làm việc.",mn:'"Hết tạm hoãn: 15 ngày trở lại".',t:"m",q:"Theo Bộ Luật Lao động, trong thời hạn bao nhiêu ngày kể từ ngày hết thời hạn tạm hoãn thực hiện hợp đồng lao động, người lao động phải có mặt tại nơi làm việc?",o:["30 ngày","07 ngày","15 ngày","10 ngày"],c:2},{id:"vb14-32",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 33",gt:"Phải báo trước ít nhất 03 ngày làm việc về nội dung cần sửa đổi, bổ sung.",mn:'"Sửa hợp đồng: báo trước 3 ngày làm việc".',t:"m",q:"Theo Bộ Luật Lao động, khi một bên có yêu cầu sửa đổi, bổ sung nội dung hợp đồng lao động thì phải báo cho bên kia biết trước ít nhất bao nhiêu?",o:["05 ngày làm việc","07 ngày làm việc","10 ngày làm việc","03 ngày làm việc"],c:3},{id:"vb14-33",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 35",gt:"Với hợp đồng không xác định thời hạn, người lao động phải báo trước ít nhất 45 ngày.",mn:'"Không xác định thời hạn: báo trước 45 ngày".',t:"m",q:"Theo Bộ Luật Lao động, người lao động làm việc theo hợp đồng lao động không xác định thời hạn khi đơn phương chấm dứt phải báo trước ít nhất bao nhiêu ngày?",o:["45 ngày","30 ngày","03 ngày làm việc","60 ngày"],c:0},{id:"vb14-34",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 35",gt:"Với hợp đồng xác định thời hạn từ 12 đến 36 tháng, phải báo trước ít nhất 30 ngày.",mn:'"12–36 tháng: báo trước 30 ngày".',t:"m",q:"Theo Bộ Luật Lao động, người lao động làm việc theo hợp đồng lao động xác định thời hạn từ 12 tháng đến 36 tháng khi đơn phương chấm dứt phải báo trước ít nhất bao nhiêu ngày?",o:["45 ngày","30 ngày","03 ngày làm việc","15 ngày"],c:1},{id:"vb14-35",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 35",gt:"Với hợp đồng xác định thời hạn dưới 12 tháng, phải báo trước ít nhất 03 ngày làm việc.",mn:'"Dưới 12 tháng: báo trước 3 ngày làm việc".',t:"m",q:"Theo Bộ Luật Lao động, người lao động làm việc theo hợp đồng lao động xác định thời hạn dưới 12 tháng khi đơn phương chấm dứt phải báo trước ít nhất bao nhiêu?",o:["30 ngày","45 ngày","03 ngày làm việc","07 ngày làm việc"],c:2},{id:"vb14-36",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 36",gt:"Người sử dụng lao động được đơn phương chấm dứt khi người lao động tự ý bỏ việc từ 05 ngày làm việc liên tục trở lên mà không có lý do chính đáng.",mn:'"Bỏ việc 5 ngày liên tục: bị chấm dứt".',t:"m",q:"Theo Bộ Luật Lao động, người sử dụng lao động có quyền đơn phương chấm dứt hợp đồng khi người lao động tự ý bỏ việc mà không có lý do chính đáng từ bao nhiêu ngày làm việc liên tục trở lên?",o:["03 ngày làm việc liên tục","07 ngày làm việc liên tục","10 ngày làm việc liên tục","05 ngày làm việc liên tục"],c:3},{id:"vb14-37",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 36",gt:"Với hợp đồng không xác định thời hạn, điều kiện là đã điều trị 12 tháng liên tục mà chưa hồi phục.",mn:'"Không xác định thời hạn: điều trị 12 tháng".',t:"m",q:"Theo Bộ Luật Lao động, người sử dụng lao động được đơn phương chấm dứt hợp đồng không xác định thời hạn khi người lao động bị ốm đau, tai nạn đã điều trị liên tục trong bao lâu mà khả năng lao động chưa hồi phục?",o:["12 tháng liên tục","06 tháng liên tục","09 tháng liên tục","03 tháng liên tục"],c:0},{id:"vb14-38",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 37",gt:"Không được đơn phương chấm dứt với người lao động đang nuôi con dưới 12 tháng tuổi, đang mang thai hoặc nghỉ thai sản.",mn:'"Nuôi con dưới 12 tháng: không bị chấm dứt".',t:"m",q:"Theo Bộ Luật Lao động, người sử dụng lao động KHÔNG được đơn phương chấm dứt hợp đồng lao động khi người lao động đang nuôi con dưới bao nhiêu tháng tuổi?",o:["06 tháng tuổi","12 tháng tuổi","24 tháng tuổi","36 tháng tuổi"],c:1},{id:"vb14-39",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 40",gt:"Người lao động chấm dứt trái pháp luật phải bồi thường nửa tháng tiền lương theo hợp đồng và tiền lương những ngày không báo trước, không được trợ cấp thôi việc.",mn:'"NLĐ sai: bồi thường nửa tháng lương".',t:"m",q:"Theo Bộ Luật Lao động, người lao động đơn phương chấm dứt hợp đồng lao động trái pháp luật phải bồi thường cho người sử dụng lao động bao nhiêu tiền lương theo hợp đồng?",o:["01 tháng tiền lương","02 tháng tiền lương","Nửa tháng tiền lương","03 tháng tiền lương"],c:2},{id:"vb14-40",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 41",gt:"Người sử dụng lao động chấm dứt trái pháp luật phải trả thêm ít nhất 02 tháng tiền lương theo hợp đồng, ngoài tiền lương và bảo hiểm những ngày không được làm việc.",mn:'"NSDLĐ sai: trả thêm ít nhất 2 tháng lương".',t:"m",q:"Theo Bộ Luật Lao động, khi người sử dụng lao động đơn phương chấm dứt hợp đồng trái pháp luật và nhận lại người lao động thì phải trả thêm một khoản tiền ít nhất bằng bao nhiêu tiền lương theo hợp đồng?",o:["01 tháng tiền lương","03 tháng tiền lương","Nửa tháng tiền lương","02 tháng tiền lương"],c:3},{id:"vb14-41",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 42",gt:"Việc cho thôi việc chỉ tiến hành sau khi trao đổi với tổ chức đại diện người lao động và thông báo trước 30 ngày cho Ủy ban nhân dân cấp tỉnh và người lao động.",mn:'"Thôi việc vì cơ cấu: báo trước 30 ngày".',t:"m",q:"Theo Bộ Luật Lao động, khi cho người lao động thôi việc do thay đổi cơ cấu, công nghệ hoặc vì lý do kinh tế, người sử dụng lao động phải thông báo trước cho Ủy ban nhân dân cấp tỉnh và người lao động bao nhiêu ngày?",o:["30 ngày","15 ngày","45 ngày","60 ngày"],c:0},{id:"vb14-42",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 44",gt:"Phương án sử dụng lao động phải được thông báo công khai trong 15 ngày kể từ ngày được thông qua.",mn:'"Phương án SDLĐ: công khai 15 ngày".',t:"m",q:"Theo Bộ Luật Lao động, phương án sử dụng lao động phải được thông báo công khai cho người lao động biết trong thời hạn bao nhiêu ngày kể từ ngày được thông qua?",o:["30 ngày","15 ngày","07 ngày","10 ngày"],c:1},{id:"vb14-43",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 46",gt:"Trợ cấp thôi việc: mỗi năm làm việc được trợ cấp một nửa tháng tiền lương (áp dụng cho người làm việc thường xuyên từ đủ 12 tháng trở lên).",mn:'"Thôi việc: mỗi năm nửa tháng lương".',t:"m",q:"Theo Bộ Luật Lao động, người sử dụng lao động trả trợ cấp thôi việc cho người lao động đã làm việc thường xuyên từ đủ 12 tháng trở lên với mức mỗi năm làm việc là bao nhiêu?",o:["Một tháng tiền lương","Hai tháng tiền lương","Một nửa tháng tiền lương","Một phần ba tháng tiền lương"],c:2},{id:"vb14-44",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 46",gt:"Tiền lương tính trợ cấp thôi việc là bình quân 06 tháng liền kề trước khi thôi việc.",mn:'"Trợ cấp thôi việc: bình quân 6 tháng".',t:"m",q:"Theo Bộ Luật Lao động, tiền lương để tính trợ cấp thôi việc là tiền lương bình quân của mấy tháng liền kề theo hợp đồng lao động trước khi người lao động thôi việc?",o:["03 tháng liền kề","12 tháng liền kề","09 tháng liền kề","06 tháng liền kề"],c:3},{id:"vb14-45",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 47",gt:"Trợ cấp mất việc làm: mỗi năm làm việc trả 01 tháng tiền lương nhưng ít nhất bằng 02 tháng tiền lương.",mn:'"Mất việc: mỗi năm 1 tháng, tối thiểu 2 tháng".',t:"m",q:"Theo Bộ Luật Lao động, trợ cấp mất việc làm được trả cho người lao động đã làm việc thường xuyên từ đủ 12 tháng trở lên với mức mỗi năm làm việc trả 01 tháng tiền lương nhưng ít nhất bằng bao nhiêu?",o:["02 tháng tiền lương","01 tháng tiền lương","03 tháng tiền lương","Nửa tháng tiền lương"],c:0},{id:"vb14-46",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 48",gt:"Trong 14 ngày làm việc kể từ ngày chấm dứt, hai bên phải thanh toán đầy đủ (một số trường hợp có thể kéo dài nhưng không quá 30 ngày).",mn:'"Chấm dứt: 14 ngày làm việc thanh toán".',t:"m",q:"Theo Bộ Luật Lao động, trong thời hạn bao nhiêu ngày làm việc kể từ ngày chấm dứt hợp đồng lao động, hai bên có trách nhiệm thanh toán đầy đủ các khoản tiền liên quan đến quyền lợi của mỗi bên?",o:["30 ngày làm việc","14 ngày làm việc","07 ngày làm việc","45 ngày làm việc"],c:1},{id:"vb14-47",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 50",gt:"Tòa án nhân dân có quyền tuyên bố hợp đồng lao động vô hiệu.",mn:'"Vô hiệu hợp đồng: Tòa án tuyên".',t:"m",q:"Theo Bộ Luật Lao động, cơ quan nào có quyền tuyên bố hợp đồng lao động vô hiệu?",o:["Cơ quan chuyên môn về lao động cấp tỉnh","Ủy ban nhân dân cấp xã","Tòa án nhân dân","Thanh tra lao động"],c:2},{id:"vb14-48",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 53",gt:"Thời hạn cho thuê lại lao động đối với người lao động tối đa là 12 tháng.",mn:'"Thuê lại lao động: tối đa 12 tháng".',t:"m",q:"Theo Bộ Luật Lao động, thời hạn cho thuê lại lao động đối với người lao động tối đa là bao nhiêu?",o:["06 tháng","24 tháng","36 tháng","12 tháng"],c:3},{id:"vb14-49",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 61",gt:"Thời hạn tập nghề không quá 03 tháng.",mn:'"Tập nghề tối đa 3 tháng".',t:"m",q:"Theo Bộ Luật Lao động, thời hạn tập nghề để làm việc cho người sử dụng lao động tối đa là bao lâu?",o:["Không quá 03 tháng","Không quá 06 tháng","Không quá 01 tháng","Không quá 12 tháng"],c:0},{id:"vb14-50",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 61",gt:"Người học nghề, tập nghề phải đủ 14 tuổi trở lên và có sức khỏe phù hợp; với nghề nặng nhọc, độc hại phải từ đủ 18 tuổi.",mn:'"Học nghề, tập nghề: đủ 14 tuổi".',t:"m",q:"Theo Bộ Luật Lao động, người học nghề, người tập nghề để làm việc cho người sử dụng lao động phải đủ bao nhiêu tuổi trở lên (đối với nghề, công việc thông thường)?",o:["Đủ 15 tuổi trở lên","Đủ 14 tuổi trở lên","Đủ 16 tuổi trở lên","Đủ 13 tuổi trở lên"],c:1},{id:"vb14-51",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 61",gt:"Người sử dụng lao động tuyển người vào học nghề, tập nghề để làm việc cho mình thì không được thu học phí.",mn:'"Học nghề để làm cho mình: miễn học phí".',t:"m",q:"Theo Bộ Luật Lao động, khi người sử dụng lao động tuyển người vào học nghề, tập nghề để làm việc cho mình thì được thu học phí như thế nào?",o:["Được thu học phí theo thỏa thuận","Được thu tối đa 50% học phí","Không được thu học phí","Được thu học phí trong 3 tháng đầu"],c:2},{id:"vb14-52",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 61",gt:"Với nghề, công việc nặng nhọc, độc hại, nguy hiểm thì người học nghề, tập nghề phải từ đủ 18 tuổi trở lên, trừ nghệ thuật, thể dục, thể thao.",mn:'"Nghề độc hại: từ đủ 18 tuổi".',t:"m",q:"Theo Bộ Luật Lao động, đối với người học nghề, tập nghề thuộc danh mục nghề, công việc nặng nhọc, độc hại, nguy hiểm thì phải đủ bao nhiêu tuổi trở lên (trừ lĩnh vực nghệ thuật, thể dục, thể thao)?",o:["Đủ 16 tuổi trở lên","Đủ 15 tuổi trở lên","Đủ 14 tuổi trở lên","Đủ 18 tuổi trở lên"],c:3},{id:"vb14-53",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 63",gt:"Người sử dụng lao động phải tổ chức đối thoại tại nơi làm việc định kỳ ít nhất 01 năm một lần, khi có yêu cầu của một hoặc các bên, và khi có vụ việc phát sinh.",mn:'"Đối thoại định kỳ: ít nhất 1 năm/lần".',t:"m",q:"Theo Bộ Luật Lao động, ngoài các trường hợp có yêu cầu hoặc khi có vụ việc phát sinh, người sử dụng lao động phải tổ chức đối thoại tại nơi làm việc theo định kỳ tối thiểu như thế nào?",o:["Định kỳ ít nhất 01 năm một lần","Định kỳ ít nhất 06 tháng một lần","Định kỳ ít nhất 03 tháng một lần","Định kỳ ít nhất 02 năm một lần"],c:0},{id:"vb14-54",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 63",gt:"Đối thoại là việc chia sẻ thông tin, tham khảo, thảo luận, trao đổi ý kiến nhằm tăng cường hiểu biết, hợp tác, hướng tới giải pháp các bên cùng có lợi.",mn:'"Đối thoại = chia sẻ – tham khảo – thảo luận".',t:"m",q:"Theo Bộ Luật Lao động, đối thoại tại nơi làm việc được hiểu là hoạt động nào giữa người sử dụng lao động với người lao động hoặc tổ chức đại diện người lao động?",o:["Bắt buộc ký kết thỏa thuận có giá trị pháp lý sau mỗi lần trao đổi","Chia sẻ thông tin, tham khảo, thảo luận, trao đổi ý kiến về những vấn đề liên quan đến quyền, lợi ích và mối quan tâm của các bên","Đàm phán để xác lập điều kiện lao động và ký thỏa ước lao động tập thể","Ra quyết định đơn phương của người sử dụng lao động về điều kiện làm việc"],c:1},{id:"vb14-55",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 66",gt:"Thương lượng tập thể theo nguyên tắc tự nguyện, hợp tác, thiện chí, bình đẳng, công khai và minh bạch.",mn:'"Tự nguyện – hợp tác – thiện chí – bình đẳng – công khai – minh bạch".',t:"m",q:"Theo Bộ Luật Lao động, thương lượng tập thể được tiến hành theo các nguyên tắc nào?",o:["Bắt buộc, tập trung, thống nhất và phục tùng cấp trên","Bí mật tuyệt đối và ưu tiên lợi ích người sử dụng lao động","Tự nguyện, hợp tác, thiện chí, bình đẳng, công khai và minh bạch","Do cơ quan quản lý nhà nước quyết định và áp đặt"],c:2},{id:"vb14-56",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 67",gt:"Nội dung thương lượng tập thể có thể gồm tiền lương, trợ cấp, nâng lương, thưởng, bữa ăn và các chế độ khác, cùng nhiều nội dung khác về lao động.",mn:'"Thương lượng: tiền lương – thưởng – bữa ăn – chế độ".',t:"m",q:"Theo Bộ Luật Lao động, nội dung nào dưới đây thuộc các nội dung mà các bên có thể lựa chọn để tiến hành thương lượng tập thể?",o:["Việc bổ nhiệm cán bộ quản lý nhà nước tại địa phương","Định mức thu ngân sách của cơ quan thuế","Quy hoạch sử dụng đất của cấp tỉnh","Tiền lương, trợ cấp, nâng lương, thưởng, bữa ăn và các chế độ khác"],c:3},{id:"vb14-57",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 70",gt:"Trong thời hạn 07 ngày làm việc kể từ ngày nhận được yêu cầu, các bên thỏa thuận về địa điểm, thời gian bắt đầu thương lượng.",mn:'"Thỏa thuận địa điểm – thời gian: 7 ngày làm việc".',t:"m",q:"Theo Bộ Luật Lao động, kể từ ngày nhận được yêu cầu và nội dung thương lượng, trong thời hạn bao lâu các bên phải thỏa thuận về địa điểm, thời gian bắt đầu thương lượng tập thể?",o:["07 ngày làm việc","10 ngày làm việc","15 ngày làm việc","30 ngày làm việc"],c:0},{id:"vb14-58",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 70",gt:"Thời gian bắt đầu thương lượng không được quá 30 ngày kể từ ngày nhận được yêu cầu thương lượng tập thể.",mn:'"Bắt đầu thương lượng: không quá 30 ngày".',t:"m",q:"Theo Bộ Luật Lao động, thời gian bắt đầu thương lượng tập thể tại doanh nghiệp không được quá bao lâu kể từ ngày nhận được yêu cầu thương lượng?",o:["Không được quá 07 ngày","Không được quá 30 ngày","Không được quá 60 ngày","Không được quá 90 ngày"],c:1},{id:"vb14-59",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 70",gt:"Thời gian thương lượng tập thể không được quá 90 ngày kể từ ngày bắt đầu thương lượng, trừ khi các bên thỏa thuận khác.",mn:'"Thương lượng: không quá 90 ngày".',t:"m",q:"Theo Bộ Luật Lao động, thời gian thương lượng tập thể không được quá bao lâu kể từ ngày bắt đầu thương lượng, trừ trường hợp các bên có thỏa thuận khác?",o:["Không được quá 30 ngày","Không được quá 60 ngày","Không được quá 90 ngày","Không được quá 180 ngày"],c:2},{id:"vb14-60",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 76",gt:"Thỏa ước lao động tập thể doanh nghiệp chỉ được ký kết khi có trên 50% người lao động của doanh nghiệp biểu quyết tán thành.",mn:'"Ký thỏa ước doanh nghiệp: trên 50% tán thành".',t:"m",q:"Theo Bộ Luật Lao động, thỏa ước lao động tập thể doanh nghiệp chỉ được ký kết khi có bao nhiêu người lao động của doanh nghiệp biểu quyết tán thành?",o:["Ít nhất 2/3 người lao động của doanh nghiệp","Trên 75% người lao động của doanh nghiệp","100% người lao động của doanh nghiệp","Trên 50% người lao động của doanh nghiệp"],c:3},{id:"vb14-61",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 77",gt:"Trong thời hạn 10 ngày kể từ ngày ký kết, người sử dụng lao động phải gửi 01 bản thỏa ước đến cơ quan chuyên môn về lao động thuộc Ủy ban nhân dân cấp tỉnh nơi đặt trụ sở chính.",mn:'"Gửi thỏa ước: 10 ngày".',t:"m",q:"Theo Bộ Luật Lao động, trong thời hạn bao lâu kể từ ngày thỏa ước lao động tập thể được ký kết, người sử dụng lao động phải gửi 01 bản đến cơ quan chuyên môn về lao động thuộc Ủy ban nhân dân cấp tỉnh?",o:["10 ngày","07 ngày làm việc","15 ngày","30 ngày"],c:0},{id:"vb14-62",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 78",gt:"Thỏa ước lao động tập thể có thời hạn từ 01 năm đến 03 năm, thời hạn cụ thể do các bên thỏa thuận và ghi trong thỏa ước.",mn:'"Thời hạn thỏa ước: 1–3 năm".',t:"m",q:"Theo Bộ Luật Lao động, thỏa ước lao động tập thể có thời hạn trong khoảng nào do các bên thỏa thuận và ghi trong thỏa ước?",o:["Từ 06 tháng đến 01 năm","Từ 01 năm đến 03 năm","Từ 02 năm đến 05 năm","Từ 01 năm đến 05 năm"],c:1},{id:"vb14-63",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 89",gt:"Mọi chi phí cho việc thương lượng, ký kết, sửa đổi, bổ sung, gửi và công bố thỏa ước lao động tập thể do phía người sử dụng lao động chi trả.",mn:'"Chi phí thỏa ước: người sử dụng lao động trả".',t:"m",q:"Theo Bộ Luật Lao động, ai là chủ thể chi trả mọi chi phí cho việc thương lượng, ký kết, sửa đổi, bổ sung, gửi và công bố thỏa ước lao động tập thể?",o:["Tổ chức đại diện người lao động","Do hai bên chia đều chi phí","Người sử dụng lao động","Ngân sách nhà nước cấp tỉnh"],c:2},{id:"vb14-64",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 91",gt:"Mức lương tối thiểu được xác lập theo vùng, ấn định theo tháng, giờ.",mn:'"Lương tối thiểu: theo vùng – ấn định tháng, giờ".',t:"m",q:"Theo Bộ Luật Lao động, mức lương tối thiểu được xác lập và ấn định theo tiêu chí nào?",o:["Được xác lập theo ngành, ấn định theo năm","Được xác lập theo tỉnh, ấn định theo tuần","Được xác lập chung toàn quốc, ấn định theo ngày","Được xác lập theo vùng, ấn định theo tháng, giờ"],c:3},{id:"vb14-65",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 90",gt:"Mức lương theo công việc hoặc chức danh không được thấp hơn mức lương tối thiểu.",mn:'"Lương công việc ≥ lương tối thiểu".',t:"m",q:"Theo Bộ Luật Lao động, mức lương theo công việc hoặc chức danh của người lao động phải bảo đảm điều kiện nào?",o:["Không được thấp hơn mức lương tối thiểu","Không được cao hơn mức lương tối thiểu","Bằng đúng mức lương tối thiểu vùng","Do người lao động tự quyết định"],c:0},{id:"vb14-66",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 96",gt:"Hai bên thỏa thuận hình thức trả lương theo thời gian, sản phẩm hoặc khoán; lương trả bằng tiền mặt hoặc qua tài khoản ngân hàng.",mn:'"Trả lương: thời gian – sản phẩm – khoán".',t:"m",q:"Theo Bộ Luật Lao động, người sử dụng lao động và người lao động có thể thỏa thuận về hình thức trả lương theo các hình thức nào?",o:["Chỉ theo thời gian làm việc thực tế","Theo thời gian, sản phẩm hoặc khoán","Chỉ theo sản lượng và doanh thu","Theo bậc lương do Nhà nước quy định"],c:1},{id:"vb14-67",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 97",gt:"Người hưởng lương theo giờ, ngày, tuần được trả sau mỗi kỳ hoặc trả gộp theo thỏa thuận nhưng không quá 15 ngày phải được trả gộp một lần.",mn:'"Trả gộp lương giờ/ngày/tuần: không quá 15 ngày".',t:"m",q:"Theo Bộ Luật Lao động, người lao động hưởng lương theo giờ, ngày, tuần nếu được trả gộp thì khoảng thời gian trả gộp một lần tối đa là bao lâu?",o:["Không quá 30 ngày phải được trả gộp một lần","Không quá 07 ngày phải được trả gộp một lần","Không quá 15 ngày phải được trả gộp một lần","Không quá 01 tháng phải được trả gộp một lần"],c:2},{id:"vb14-68",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 97",gt:"Vì lý do bất khả kháng đã tìm mọi biện pháp khắc phục, việc trả lương chậm không được quá 30 ngày; chậm từ 15 ngày trở lên phải đền bù một khoản tiền lãi.",mn:'"Chậm lương bất khả kháng: không quá 30 ngày".',t:"m",q:"Theo Bộ Luật Lao động, trường hợp vì lý do bất khả kháng mà không thể trả lương đúng hạn thì người sử dụng lao động không được chậm quá bao lâu?",o:["Không được chậm quá 15 ngày","Không được chậm quá 45 ngày","Không được chậm quá 60 ngày","Không được chậm quá 30 ngày"],c:3},{id:"vb14-69",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 98",gt:"Làm thêm giờ vào ngày thường được trả ít nhất bằng 150%; ngày nghỉ hằng tuần ít nhất 200%; ngày nghỉ lễ, tết ít nhất 300%.",mn:'"Thêm giờ ngày thường: ≥150%".',t:"m",q:"Theo Bộ Luật Lao động, người lao động làm thêm giờ vào ngày thường thì được trả lương ít nhất bằng bao nhiêu so với đơn giá tiền lương hoặc tiền lương thực trả?",o:["Ít nhất bằng 150%","Ít nhất bằng 200%","Ít nhất bằng 130%","Ít nhất bằng 300%"],c:0},{id:"vb14-70",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 98",gt:"Làm thêm giờ vào ngày nghỉ lễ, tết, ngày nghỉ có hưởng lương được trả ít nhất bằng 300%, chưa kể tiền lương ngày lễ, tết đối với người hưởng lương ngày.",mn:'"Thêm giờ ngày lễ, tết: ≥300%".',t:"m",q:"Theo Bộ Luật Lao động, người lao động làm thêm giờ vào ngày nghỉ lễ, tết, ngày nghỉ có hưởng lương thì được trả lương ít nhất bằng bao nhiêu, chưa kể tiền lương ngày lễ, tết đối với người hưởng lương ngày?",o:["Ít nhất bằng 200%","Ít nhất bằng 300%","Ít nhất bằng 150%","Ít nhất bằng 400%"],c:1},{id:"vb14-71",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 98",gt:"Làm việc vào ban đêm được trả thêm ít nhất bằng 30% tiền lương tính theo đơn giá hoặc tiền lương thực trả của ngày làm việc bình thường.",mn:'"Làm ban đêm: trả thêm ≥30%".',t:"m",q:"Theo Bộ Luật Lao động, người lao động làm việc vào ban đêm thì được trả thêm ít nhất bằng bao nhiêu tiền lương so với công việc của ngày làm việc bình thường?",o:["Ít nhất bằng 20%","Ít nhất bằng 50%","Ít nhất bằng 30%","Ít nhất bằng 150%"],c:2},{id:"vb14-72",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 98",gt:"Làm thêm giờ vào ban đêm, ngoài lương làm thêm và lương ban đêm, người lao động còn được trả thêm 20% tiền lương của công việc làm vào ban ngày của ngày bình thường.",mn:'"Thêm giờ ban đêm: cộng thêm 20%".',t:"m",q:"Theo Bộ Luật Lao động, ngoài lương làm thêm và lương ban đêm, người lao động làm thêm giờ vào ban đêm còn được trả thêm bao nhiêu tiền lương tính theo công việc làm vào ban ngày của ngày làm việc bình thường?",o:["Trả thêm 30%","Trả thêm 10%","Trả thêm 50%","Trả thêm 20%"],c:3},{id:"vb14-73",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 99",gt:"Ngừng việc do lỗi của người sử dụng lao động thì người lao động được trả đủ tiền lương theo hợp đồng lao động.",mn:'"Ngừng việc do lỗi chủ: trả đủ lương".',t:"m",q:"Theo Bộ Luật Lao động, trường hợp phải ngừng việc do lỗi của người sử dụng lao động thì người lao động được trả lương như thế nào?",o:["Được trả đủ tiền lương theo hợp đồng lao động","Được trả 70% tiền lương theo hợp đồng","Không được trả lương trong thời gian ngừng việc","Được trả bằng mức lương tối thiểu vùng"],c:0},{id:"vb14-74",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 102",gt:"Mức khấu trừ tiền lương hằng tháng không được quá 30% tiền lương thực trả sau khi trích nộp bảo hiểm xã hội bắt buộc, bảo hiểm y tế, bảo hiểm thất nghiệp, thuế thu nhập cá nhân.",mn:'"Khấu trừ lương: không quá 30%/tháng".',t:"m",q:"Theo Bộ Luật Lao động, mức khấu trừ tiền lương hằng tháng của người lao động không được quá bao nhiêu tiền lương thực trả hằng tháng sau khi trích nộp các khoản bảo hiểm bắt buộc và thuế thu nhập cá nhân?",o:["Không được quá 50%","Không được quá 30%","Không được quá 20%","Không được quá 10%"],c:1},{id:"vb14-75",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 102",gt:"Người sử dụng lao động chỉ được khấu trừ tiền lương để bồi thường thiệt hại do làm hư hỏng dụng cụ, thiết bị, tài sản của người sử dụng lao động; người lao động có quyền được biết lý do khấu trừ.",mn:'"Chỉ khấu trừ để bồi thường hư hỏng tài sản".',t:"m",q:"Theo Bộ Luật Lao động, người sử dụng lao động chỉ được khấu trừ tiền lương của người lao động trong trường hợp nào?",o:["Để thu hồi mọi khoản tạm ứng lương chưa hoàn trả","Để nộp thay các khoản phạt hành chính của người lao động","Để bồi thường thiệt hại do làm hư hỏng dụng cụ, thiết bị, tài sản của người sử dụng lao động","Để trừ vào chi phí đào tạo nghề của doanh nghiệp"],c:2},{id:"vb14-76",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 105",gt:"Thời giờ làm việc bình thường không quá 08 giờ/ngày và không quá 48 giờ/tuần; Nhà nước khuyến khích tuần làm việc 40 giờ.",mn:'"Bình thường: 8 giờ/ngày – 48 giờ/tuần".',t:"m",q:"Theo Bộ Luật Lao động, thời giờ làm việc bình thường của người lao động được quy định tối đa như thế nào?",o:["Không quá 10 giờ trong 01 ngày và không quá 50 giờ trong 01 tuần","Không quá 08 giờ trong 01 ngày và không quá 40 giờ trong 01 tuần","Không quá 09 giờ trong 01 ngày và không quá 48 giờ trong 01 tuần","Không quá 08 giờ trong 01 ngày và không quá 48 giờ trong 01 tuần"],c:3},{id:"vb14-77",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 105",gt:"Khi quy định theo tuần, thời giờ làm việc bình thường không quá 10 giờ/ngày và không quá 48 giờ/tuần.",mn:'"Theo tuần: 10 giờ/ngày – 48 giờ/tuần".',t:"m",q:"Theo Bộ Luật Lao động, trường hợp quy định thời giờ làm việc bình thường theo tuần thì thời giờ làm việc không quá bao nhiêu giờ trong 01 ngày và bao nhiêu giờ trong 01 tuần?",o:["Không quá 10 giờ trong 01 ngày và không quá 48 giờ trong 01 tuần","Không quá 08 giờ trong 01 ngày và không quá 48 giờ trong 01 tuần","Không quá 12 giờ trong 01 ngày và không quá 48 giờ trong 01 tuần","Không quá 10 giờ trong 01 ngày và không quá 40 giờ trong 01 tuần"],c:0},{id:"vb14-78",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 106",gt:"Giờ làm việc ban đêm được tính từ 22 giờ đến 06 giờ sáng ngày hôm sau.",mn:'"Ban đêm: 22h – 6h".',t:"m",q:"Theo Bộ Luật Lao động, giờ làm việc ban đêm được tính trong khoảng thời gian nào?",o:["Từ 21 giờ đến 05 giờ sáng ngày hôm sau","Từ 22 giờ đến 06 giờ sáng ngày hôm sau","Từ 23 giờ đến 06 giờ sáng ngày hôm sau","Từ 22 giờ đến 05 giờ sáng ngày hôm sau"],c:1},{id:"vb14-79",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 107",gt:"Số giờ làm thêm phải bảo đảm không quá 50% giờ làm việc bình thường trong ngày và không quá 40 giờ trong 01 tháng.",mn:'"Làm thêm: không quá 40 giờ/tháng".',t:"m",q:"Theo Bộ Luật Lao động, số giờ làm thêm của người lao động được bảo đảm không quá bao nhiêu trong 01 tháng?",o:["Không quá 30 giờ trong 01 tháng","Không quá 50 giờ trong 01 tháng","Không quá 40 giờ trong 01 tháng","Không quá 60 giờ trong 01 tháng"],c:2},{id:"vb14-80",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 107",gt:"Số giờ làm thêm bảo đảm không quá 200 giờ trong 01 năm, trừ một số ngành, nghề, công việc hoặc trường hợp đặc biệt được làm không quá 300 giờ.",mn:'"Làm thêm: ≤200 giờ/năm (đặc biệt 300)".',t:"m",q:"Theo Bộ Luật Lao động, số giờ làm thêm của người lao động trong 01 năm được bảo đảm không quá bao nhiêu, trừ một số ngành, nghề, công việc đặc biệt?",o:["Không quá 300 giờ trong 01 năm","Không quá 150 giờ trong 01 năm","Không quá 250 giờ trong 01 năm","Không quá 200 giờ trong 01 năm"],c:3},{id:"vb14-81",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 107",gt:"Với một số ngành, nghề như dệt, may, da, giày, điện, điện tử, chế biến thủy sản… được làm thêm không quá 300 giờ trong 01 năm.",mn:'"Đặc biệt: ≤300 giờ/năm".',t:"m",q:"Theo Bộ Luật Lao động, trong một số ngành, nghề, công việc hoặc trường hợp đặc biệt, người sử dụng lao động được sử dụng người lao động làm thêm tối đa bao nhiêu giờ trong 01 năm?",o:["Không quá 300 giờ trong 01 năm","Không quá 200 giờ trong 01 năm","Không quá 400 giờ trong 01 năm","Không quá 350 giờ trong 01 năm"],c:0},{id:"vb14-82",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 109",gt:"Làm việc từ 06 giờ trở lên trong ngày được nghỉ giữa giờ ít nhất 30 phút liên tục; làm việc ban đêm thì được nghỉ ít nhất 45 phút liên tục.",mn:'"Nghỉ giữa giờ ban ngày: ≥30 phút".',t:"m",q:"Theo Bộ Luật Lao động, người lao động làm việc từ 06 giờ trở lên trong một ngày (làm việc ban ngày) thì được nghỉ giữa giờ ít nhất bao nhiêu phút liên tục?",o:["Ít nhất 45 phút liên tục","Ít nhất 30 phút liên tục","Ít nhất 60 phút liên tục","Ít nhất 15 phút liên tục"],c:1},{id:"vb14-83",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 110",gt:"Người lao động làm việc theo ca được nghỉ ít nhất 12 giờ trước khi chuyển sang ca làm việc khác.",mn:'"Nghỉ chuyển ca: ≥12 giờ".',t:"m",q:"Theo Bộ Luật Lao động, người lao động làm việc theo ca được nghỉ ít nhất bao nhiêu giờ trước khi chuyển sang ca làm việc khác?",o:["Ít nhất 08 giờ","Ít nhất 24 giờ","Ít nhất 12 giờ","Ít nhất 10 giờ"],c:2},{id:"vb14-84",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 111",gt:"Mỗi tuần người lao động được nghỉ ít nhất 24 giờ liên tục; trường hợp đặc biệt phải bảo đảm bình quân 01 tháng ít nhất 04 ngày.",mn:'"Nghỉ hằng tuần: ≥24 giờ liên tục".',t:"m",q:"Theo Bộ Luật Lao động, mỗi tuần người lao động được nghỉ hằng tuần ít nhất bao nhiêu giờ liên tục?",o:["Ít nhất 12 giờ liên tục","Ít nhất 48 giờ liên tục","Ít nhất 36 giờ liên tục","Ít nhất 24 giờ liên tục"],c:3},{id:"vb14-85",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 112",gt:"Dịp Tết Âm lịch người lao động được nghỉ 05 ngày hưởng nguyên lương; Quốc khánh nghỉ 02 ngày.",mn:'"Tết Âm lịch: nghỉ 5 ngày".',t:"m",q:"Theo Bộ Luật Lao động, dịp Tết Âm lịch người lao động được nghỉ làm việc, hưởng nguyên lương bao nhiêu ngày?",o:["05 ngày","04 ngày","03 ngày","02 ngày"],c:0},{id:"vb14-86",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 112",gt:"Dịp Quốc khánh người lao động được nghỉ 02 ngày (ngày 02/9 dương lịch và 01 ngày liền kề trước hoặc sau).",mn:'"Quốc khánh: nghỉ 2 ngày".',t:"m",q:"Theo Bộ Luật Lao động, dịp Quốc khánh người lao động được nghỉ làm việc, hưởng nguyên lương bao nhiêu ngày?",o:["01 ngày","02 ngày","03 ngày","05 ngày"],c:1},{id:"vb14-87",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 113",gt:"Làm đủ 12 tháng trong điều kiện bình thường được nghỉ hằng năm 12 ngày làm việc; 14 ngày với công việc nặng nhọc, độc hại; 16 ngày với công việc đặc biệt nặng nhọc.",mn:'"Nghỉ hằng năm bình thường: 12 ngày".',t:"m",q:"Theo Bộ Luật Lao động, người lao động làm việc đủ 12 tháng cho một người sử dụng lao động, làm công việc trong điều kiện bình thường thì được nghỉ hằng năm hưởng nguyên lương bao nhiêu ngày?",o:["14 ngày làm việc","16 ngày làm việc","12 ngày làm việc","10 ngày làm việc"],c:2},{id:"vb14-88",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 113",gt:"Người làm công việc đặc biệt nặng nhọc, độc hại, nguy hiểm được nghỉ hằng năm 16 ngày làm việc.",mn:'"Đặc biệt nặng nhọc: nghỉ 16 ngày".',t:"m",q:"Theo Bộ Luật Lao động, người lao động làm nghề, công việc đặc biệt nặng nhọc, độc hại, nguy hiểm khi làm đủ 12 tháng thì được nghỉ hằng năm hưởng nguyên lương bao nhiêu ngày?",o:["14 ngày làm việc","12 ngày làm việc","18 ngày làm việc","16 ngày làm việc"],c:3},{id:"vb14-89",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 118",gt:"Người sử dụng lao động phải ban hành nội quy lao động; nếu sử dụng từ 10 người lao động trở lên thì nội quy lao động phải bằng văn bản.",mn:'"Từ 10 lao động: nội quy bằng văn bản".',t:"m",q:"Theo Bộ Luật Lao động, người sử dụng lao động sử dụng từ bao nhiêu người lao động trở lên thì nội quy lao động phải bằng văn bản?",o:["Từ 10 người lao động trở lên","Từ 05 người lao động trở lên","Từ 20 người lao động trở lên","Từ 15 người lao động trở lên"],c:0},{id:"vb14-90",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 119",gt:"Trong thời hạn 10 ngày kể từ ngày ban hành nội quy lao động, người sử dụng lao động phải nộp hồ sơ đăng ký tại cơ quan chuyên môn về lao động thuộc Ủy ban nhân dân cấp tỉnh.",mn:'"Nộp hồ sơ đăng ký nội quy: 10 ngày".',t:"m",q:"Theo Bộ Luật Lao động, trong thời hạn bao lâu kể từ ngày ban hành nội quy lao động, người sử dụng lao động phải nộp hồ sơ đăng ký nội quy lao động?",o:["Trong thời hạn 07 ngày làm việc","Trong thời hạn 10 ngày","Trong thời hạn 15 ngày","Trong thời hạn 30 ngày"],c:1},{id:"vb14-91",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 121",gt:"Nội quy lao động có hiệu lực sau 15 ngày kể từ ngày cơ quan có thẩm quyền nhận được đầy đủ hồ sơ đăng ký.",mn:'"Nội quy lao động: hiệu lực sau 15 ngày".',t:"m",q:"Theo Bộ Luật Lao động, nội quy lao động có hiệu lực sau bao lâu kể từ ngày cơ quan nhà nước có thẩm quyền nhận được đầy đủ hồ sơ đăng ký nội quy lao động?",o:["Sau 07 ngày làm việc","Sau 10 ngày","Sau 15 ngày","Sau 30 ngày"],c:2},{id:"vb14-92",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 122",gt:"Khi xử lý kỷ luật, người sử dụng lao động phải chứng minh được lỗi của người lao động, có sự tham gia của tổ chức đại diện người lao động và phải lập biên bản.",mn:'"Chủ phải chứng minh lỗi người lao động".',t:"m",q:"Theo Bộ Luật Lao động, nguyên tắc nào dưới đây phải được bảo đảm khi xử lý kỷ luật lao động?",o:["Người lao động phải tự chứng minh mình vô tội","Được áp dụng nhiều hình thức kỷ luật cho một hành vi vi phạm","Không cần lập biên bản nếu vi phạm rõ ràng","Người sử dụng lao động phải chứng minh được lỗi của người lao động"],c:3},{id:"vb14-93",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 122",gt:"Không được áp dụng nhiều hình thức xử lý kỷ luật lao động đối với một hành vi vi phạm; nhiều hành vi thì chỉ áp dụng hình thức cao nhất tương ứng hành vi nặng nhất.",mn:'"Một hành vi – một hình thức kỷ luật".',t:"m",q:"Theo Bộ Luật Lao động, đối với một hành vi vi phạm kỷ luật lao động, việc áp dụng hình thức xử lý kỷ luật được quy định như thế nào?",o:["Không được áp dụng nhiều hình thức xử lý kỷ luật đối với một hành vi vi phạm","Được áp dụng đồng thời tất cả các hình thức kỷ luật","Bắt buộc áp dụng hình thức sa thải","Do người lao động lựa chọn hình thức kỷ luật"],c:0},{id:"vb14-94",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 123",gt:"Thời hiệu xử lý kỷ luật lao động là 06 tháng kể từ ngày xảy ra hành vi vi phạm; trường hợp liên quan trực tiếp đến tài chính, tài sản, bí mật công nghệ, kinh doanh thì là 12 tháng.",mn:'"Thời hiệu kỷ luật: 6 tháng (tài chính/bí mật: 12)".',t:"m",q:"Theo Bộ Luật Lao động, thời hiệu xử lý kỷ luật lao động thông thường là bao lâu kể từ ngày xảy ra hành vi vi phạm?",o:["12 tháng","06 tháng","03 tháng","24 tháng"],c:1},{id:"vb14-95",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 123",gt:"Hành vi liên quan trực tiếp đến tài chính, tài sản, tiết lộ bí mật công nghệ, bí mật kinh doanh thì thời hiệu xử lý kỷ luật lao động là 12 tháng.",mn:'"Liên quan tài chính/bí mật: 12 tháng".',t:"m",q:"Theo Bộ Luật Lao động, hành vi vi phạm liên quan trực tiếp đến tài chính, tài sản, tiết lộ bí mật công nghệ, bí mật kinh doanh của người sử dụng lao động thì thời hiệu xử lý kỷ luật lao động là bao lâu?",o:["06 tháng","24 tháng","12 tháng","03 tháng"],c:2},{id:"vb14-96",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 124",gt:"Các hình thức kỷ luật gồm khiển trách; kéo dài thời hạn nâng lương không quá 06 tháng; cách chức; sa thải.",mn:'"Kéo dài nâng lương: không quá 6 tháng".',t:"m",q:"Theo Bộ Luật Lao động, hình thức kỷ luật kéo dài thời hạn nâng lương được áp dụng với thời hạn tối đa là bao lâu?",o:["Không quá 03 tháng","Không quá 12 tháng","Không quá 09 tháng","Không quá 06 tháng"],c:3},{id:"vb14-97",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 125",gt:"Sa thải khi người lao động tự ý bỏ việc 05 ngày cộng dồn trong 30 ngày hoặc 20 ngày cộng dồn trong 365 ngày mà không có lý do chính đáng.",mn:'"Bỏ việc 5 ngày/30 ngày (hoặc 20/365) → sa thải".',t:"m",q:"Theo Bộ Luật Lao động, hình thức kỷ luật sa thải được áp dụng khi người lao động tự ý bỏ việc bao nhiêu ngày cộng dồn trong thời hạn 30 ngày mà không có lý do chính đáng?",o:["05 ngày cộng dồn trong 30 ngày","03 ngày cộng dồn trong 30 ngày","07 ngày cộng dồn trong 30 ngày","10 ngày cộng dồn trong 30 ngày"],c:0},{id:"vb14-98",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 126",gt:"Bị khiển trách sau 03 tháng, bị kéo dài nâng lương sau 06 tháng, bị cách chức sau 03 năm kể từ ngày bị xử lý mà không vi phạm thì đương nhiên được xóa kỷ luật.",mn:'"Xóa kỷ luật cách chức: 3 năm".',t:"m",q:"Theo Bộ Luật Lao động, người lao động bị xử lý kỷ luật cách chức thì sau bao lâu kể từ ngày bị xử lý, nếu không tiếp tục vi phạm thì đương nhiên được xóa kỷ luật?",o:["Sau 03 tháng","Sau 03 năm","Sau 06 tháng","Sau 01 năm"],c:1},{id:"vb14-99",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 127",gt:"Nghiêm cấm phạt tiền, cắt lương thay việc xử lý kỷ luật lao động; cấm xâm phạm sức khỏe, danh dự, nhân phẩm người lao động.",mn:'"Cấm phạt tiền, cắt lương thay kỷ luật".',t:"m",q:"Theo Bộ Luật Lao động, hành vi nào dưới đây bị nghiêm cấm khi xử lý kỷ luật lao động?",o:["Lập biên bản có sự tham gia của tổ chức đại diện người lao động","Cho người lao động tự bào chữa hoặc nhờ luật sư","Phạt tiền, cắt lương thay việc xử lý kỷ luật lao động","Chứng minh lỗi của người lao động trước khi xử lý"],c:2},{id:"vb14-100",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 128",gt:"Thời hạn tạm đình chỉ công việc không quá 15 ngày, trường hợp đặc biệt không quá 90 ngày; người lao động được tạm ứng 50% tiền lương trước khi bị đình chỉ.",mn:'"Tạm đình chỉ: 15 ngày – tạm ứng 50%".',t:"m",q:"Theo Bộ Luật Lao động, thời hạn tạm đình chỉ công việc của người lao động thông thường không được quá bao lâu, và trong thời gian đó người lao động được tạm ứng bao nhiêu tiền lương?",o:["Không quá 30 ngày và được tạm ứng 70% tiền lương","Không quá 90 ngày và được tạm ứng đủ tiền lương","Không quá 07 ngày và không được tạm ứng lương","Không quá 15 ngày và được tạm ứng 50% tiền lương trước khi bị đình chỉ"],c:3},{id:"vb14-101",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 133",gt:"Chính phủ quyết định Chương trình quốc gia về an toàn, vệ sinh lao động; Ủy ban nhân dân cấp tỉnh trình Hội đồng nhân dân cùng cấp quyết định chương trình của địa phương.",mn:'"Chương trình quốc gia ATVSLĐ: Chính phủ quyết định".',t:"m",q:"Theo Bộ Luật Lao động, ai là chủ thể quyết định Chương trình quốc gia về an toàn, vệ sinh lao động?",o:["Chính phủ","Ủy ban nhân dân cấp tỉnh","Bộ Lao động - Thương binh và Xã hội","Hội đồng nhân dân cấp tỉnh"],c:0},{id:"vb14-102",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 133",gt:"Ủy ban nhân dân cấp tỉnh trình Hội đồng nhân dân cùng cấp quyết định Chương trình an toàn, vệ sinh lao động của địa phương.",mn:'"Địa phương: UBND cấp tỉnh trình HĐND".',t:"m",q:"Theo Bộ Luật Lao động, ở địa phương, chủ thể nào trình Hội đồng nhân dân cùng cấp quyết định Chương trình an toàn, vệ sinh lao động và đưa vào kế hoạch phát triển kinh tế - xã hội?",o:["Chính phủ","Ủy ban nhân dân cấp tỉnh","Sở Lao động - Thương binh và Xã hội","Hội đồng nhân dân cấp xã"],c:1},{id:"vb14-103",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 134",gt:"Người sử dụng lao động có trách nhiệm thực hiện đầy đủ các giải pháp nhằm bảo đảm an toàn, vệ sinh lao động tại nơi làm việc.",mn:'"Chủ: thực hiện đầy đủ giải pháp ATVSLĐ".',t:"m",q:"Theo Bộ Luật Lao động, trách nhiệm bảo đảm an toàn, vệ sinh lao động tại nơi làm việc của người sử dụng lao động được quy định như thế nào?",o:["Chỉ thực hiện khi có yêu cầu của cơ quan thanh tra","Chỉ cần mua bảo hiểm cho người lao động là đủ","Thực hiện đầy đủ các giải pháp nhằm bảo đảm an toàn, vệ sinh lao động tại nơi làm việc","Giao toàn bộ trách nhiệm cho người lao động tự bảo đảm"],c:2},{id:"vb14-104",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 132",gt:"Các chủ thể liên quan phải thực hiện quy định của pháp luật về an toàn, vệ sinh lao động (dẫn chiếu Luật An toàn, vệ sinh lao động).",mn:'"Tuân thủ pháp luật ATVSLĐ".',t:"m",q:"Theo Bộ Luật Lao động, người sử dụng lao động, người lao động và cơ quan, tổ chức, cá nhân có liên quan đến lao động, sản xuất, kinh doanh phải thực hiện quy định của pháp luật nào?",o:["Quy định của pháp luật về bảo hiểm xã hội","Quy định của pháp luật về doanh nghiệp","Quy định của pháp luật về đầu tư","Quy định của pháp luật về an toàn, vệ sinh lao động"],c:3},{id:"vb14-105",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 135",gt:"Nhà nước có chính sách giảm thuế đối với người sử dụng lao động sử dụng nhiều lao động nữ theo pháp luật về thuế.",mn:'"Giảm thuế cho nơi dùng nhiều lao động nữ".',t:"m",q:"Theo Bộ Luật Lao động, đối với người sử dụng lao động sử dụng nhiều lao động nữ, Nhà nước có chính sách ưu đãi nào sau đây theo quy định của pháp luật về thuế?",o:["Giảm thuế đối với người sử dụng lao động có sử dụng nhiều lao động nữ","Miễn toàn bộ thuế thu nhập doanh nghiệp","Hoàn thuế giá trị gia tăng đã nộp","Cấp bù ngân sách theo số lao động nữ"],c:0},{id:"vb14-106",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 136",gt:"Người sử dụng lao động phải bảo đảm có đủ buồng tắm và buồng vệ sinh phù hợp tại nơi làm việc, tham khảo ý kiến lao động nữ và hỗ trợ nhà trẻ, mẫu giáo.",mn:'"Đủ buồng tắm, buồng vệ sinh".',t:"m",q:"Theo Bộ Luật Lao động, một trong các trách nhiệm của người sử dụng lao động nhằm bảo đảm điều kiện làm việc cho lao động nữ tại nơi làm việc là gì?",o:["Xây dựng nhà ở miễn phí cho toàn bộ lao động nữ","Bảo đảm có đủ buồng tắm và buồng vệ sinh phù hợp tại nơi làm việc","Bố trí xe đưa đón riêng cho lao động nữ","Trả thêm 30% lương cho lao động nữ"],c:1},{id:"vb14-107",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 137",gt:"Không được bố trí làm ban đêm, làm thêm giờ, công tác xa khi lao động nữ mang thai từ tháng thứ 07.",mn:'"Mang thai tháng thứ 7 là dừng".',t:"m",q:"Theo Bộ Luật Lao động, người sử dụng lao động không được sử dụng người lao động làm việc ban đêm, làm thêm giờ và đi công tác xa khi lao động nữ mang thai từ thời điểm nào (trong điều kiện làm việc bình thường)?",o:["Từ tháng thứ 06","Từ tháng thứ 05","Từ tháng thứ 07","Từ tháng thứ 08"],c:2},{id:"vb14-108",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 137",gt:"Ở vùng cao, vùng sâu, vùng xa, biên giới, hải đảo, mốc bảo vệ sớm hơn: mang thai từ tháng thứ 06.",mn:'"Vùng khó khăn: tháng thứ 6".',t:"m",q:"Theo Bộ Luật Lao động, đối với lao động nữ làm việc ở vùng cao, vùng sâu, vùng xa, biên giới, hải đảo, việc không sử dụng làm ban đêm, làm thêm giờ, đi công tác xa được áp dụng khi mang thai từ thời điểm nào?",o:["Từ tháng thứ 07","Từ tháng thứ 05","Từ tháng thứ 04","Từ tháng thứ 06"],c:3},{id:"vb14-109",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 137",gt:"Được chuyển việc nhẹ hơn, an toàn hơn hoặc giảm 01 giờ/ngày không bị cắt lương cho đến hết thời gian nuôi con dưới 12 tháng tuổi.",mn:'"Việc nhẹ hơn hoặc giảm 1 giờ".',t:"m",q:"Theo Bộ Luật Lao động, lao động nữ làm nghề, công việc nặng nhọc, độc hại, nguy hiểm khi mang thai và có thông báo cho người sử dụng lao động thì được hưởng chế độ nào?",o:["Được chuyển sang công việc nhẹ hơn, an toàn hơn hoặc giảm bớt 01 giờ làm việc hằng ngày mà không bị cắt giảm tiền lương","Được nghỉ việc hưởng nguyên lương đến khi sinh","Được giảm 50% thời giờ làm việc","Được chấm dứt hợp đồng và hưởng trợ cấp"],c:0},{id:"vb14-110",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 137",gt:"Nuôi con dưới 12 tháng tuổi được nghỉ 60 phút/ngày; thời gian hành kinh được nghỉ 30 phút/ngày, vẫn hưởng đủ lương.",mn:'"Nuôi con nhỏ 60 phút, hành kinh 30 phút".',t:"m",q:"Theo Bộ Luật Lao động, lao động nữ trong thời gian nuôi con dưới 12 tháng tuổi được nghỉ mỗi ngày bao nhiêu thời gian trong giờ làm việc mà vẫn hưởng đủ lương?",o:["30 phút","60 phút","45 phút","90 phút"],c:1},{id:"vb14-111",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 139",gt:"Nghỉ thai sản 06 tháng; thời gian nghỉ trước khi sinh không quá 02 tháng.",mn:'"6 tháng, trước sinh ≤ 2 tháng".',t:"m",q:"Theo Bộ Luật Lao động, lao động nữ được nghỉ thai sản trước và sau khi sinh con trong điều kiện thông thường là bao lâu, trong đó thời gian nghỉ trước khi sinh không quá bao nhiêu?",o:["Nghỉ 04 tháng, nghỉ trước sinh không quá 01 tháng","Nghỉ 05 tháng, nghỉ trước sinh không quá 03 tháng","Nghỉ 06 tháng, thời gian nghỉ trước khi sinh không quá 02 tháng","Nghỉ 06 tháng, nghỉ trước sinh không quá 03 tháng"],c:2},{id:"vb14-112",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 139",gt:"Sinh đôi trở lên: từ con thứ hai, mỗi con nghỉ thêm 01 tháng; có thể trở lại làm việc khi đã nghỉ ít nhất 04 tháng (được đồng ý và có xác nhận y tế).",mn:'"Mỗi con thêm 1 tháng; đi làm lại sớm ≥ 4 tháng".',t:"m",q:"Theo Bộ Luật Lao động, trường hợp lao động nữ sinh đôi trở lên thì được nghỉ thai sản thêm như thế nào, và có thể trở lại làm việc sớm khi đã nghỉ ít nhất bao lâu?",o:["Mỗi con nghỉ thêm 02 tháng; trở lại làm việc sau ít nhất 03 tháng","Nghỉ thêm 01 tháng cho toàn bộ số con; trở lại sau 05 tháng","Từ con thứ ba nghỉ thêm 01 tháng; trở lại sau 02 tháng","Từ con thứ hai trở đi cứ mỗi con nghỉ thêm 01 tháng; được trở lại làm việc khi đã nghỉ ít nhất 04 tháng"],c:3},{id:"vb14-113",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 143",gt:"Lao động chưa thành niên là người lao động chưa đủ 18 tuổi.",mn:'"Chưa đủ 18 là chưa thành niên".',t:"m",q:"Theo Bộ Luật Lao động, lao động chưa thành niên là người lao động thuộc độ tuổi nào?",o:["Chưa đủ 18 tuổi","Chưa đủ 16 tuổi","Chưa đủ 15 tuổi","Từ đủ 15 đến đủ 18 tuổi"],c:0},{id:"vb14-114",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 143",gt:"Người từ đủ 13 đến chưa đủ 15 tuổi chỉ được làm công việc nhẹ theo danh mục do Bộ trưởng Bộ Lao động - Thương binh và Xã hội ban hành.",mn:'"13–15 chỉ làm việc nhẹ theo danh mục".',t:"m",q:"Theo Bộ Luật Lao động, người từ đủ 13 tuổi đến chưa đủ 15 tuổi chỉ được làm loại công việc nào?",o:["Mọi công việc trừ công việc nặng nhọc","Công việc nhẹ theo danh mục do Bộ trưởng Bộ Lao động - Thương binh và Xã hội ban hành","Công việc hành chính, văn phòng bất kỳ","Công việc do gia đình tự lựa chọn"],c:1},{id:"vb14-115",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 145",gt:"Sử dụng người chưa đủ 13 tuổi làm nghệ thuật, thể dục, thể thao phải được cơ quan chuyên môn về lao động thuộc Ủy ban nhân dân cấp tỉnh đồng ý.",mn:'"Chưa đủ 13: cơ quan LĐ cấp tỉnh đồng ý".',t:"m",q:"Theo Bộ Luật Lao động, người sử dụng lao động chỉ được sử dụng người chưa đủ 13 tuổi vào công việc nghệ thuật, thể dục, thể thao khi có sự đồng ý của cơ quan nào?",o:["Ủy ban nhân dân cấp xã nơi cư trú","Sở Giáo dục và Đào tạo","Cơ quan chuyên môn về lao động thuộc Ủy ban nhân dân cấp tỉnh","Cơ quan công an nơi doanh nghiệp đóng trụ sở"],c:2},{id:"vb14-116",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 145",gt:"Phải kiểm tra sức khỏe định kỳ ít nhất một lần trong 06 tháng cho người chưa đủ 15 tuổi.",mn:'"Khám sức khỏe 6 tháng/lần".',t:"m",q:"Theo Bộ Luật Lao động, khi sử dụng người chưa đủ 15 tuổi làm việc, người sử dụng lao động phải tổ chức kiểm tra sức khỏe định kỳ với tần suất tối thiểu nào?",o:["Ít nhất một lần trong 12 tháng","Ít nhất một lần trong 03 tháng","Ít nhất hai lần trong 06 tháng","Ít nhất một lần trong 06 tháng"],c:3},{id:"vb14-117",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 146",gt:"Người chưa đủ 15 tuổi: không quá 04 giờ/ngày và 20 giờ/tuần, không được làm thêm giờ, làm việc ban đêm.",mn:'"Chưa đủ 15: 4 giờ/ngày, 20 giờ/tuần".',t:"m",q:"Theo Bộ Luật Lao động, thời giờ làm việc của người chưa đủ 15 tuổi được giới hạn như thế nào?",o:["Không quá 04 giờ trong 01 ngày và 20 giờ trong 01 tuần; không được làm thêm giờ, làm việc ban đêm","Không quá 06 giờ trong 01 ngày và 30 giờ trong 01 tuần","Không quá 08 giờ trong 01 ngày và 40 giờ trong 01 tuần","Không quá 04 giờ trong 01 ngày nhưng được làm thêm giờ"],c:0},{id:"vb14-118",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 146",gt:"Người từ đủ 15 đến chưa đủ 18 tuổi: không quá 08 giờ/ngày và 40 giờ/tuần.",mn:'"15–18: 8 giờ/ngày, 40 giờ/tuần".',t:"m",q:"Theo Bộ Luật Lao động, thời giờ làm việc của người từ đủ 15 tuổi đến chưa đủ 18 tuổi được giới hạn như thế nào?",o:["Không quá 06 giờ trong 01 ngày và 36 giờ trong 01 tuần","Không quá 08 giờ trong 01 ngày và 40 giờ trong 01 tuần","Không quá 07 giờ trong 01 ngày và 42 giờ trong 01 tuần","Không quá 04 giờ trong 01 ngày và 20 giờ trong 01 tuần"],c:1},{id:"vb14-119",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 147",gt:"Cấm sử dụng lao động 15–18 tuổi ở sòng bạc, quán bar, vũ trường, karaoke, khách sạn, nhà nghỉ, cơ sở tắm hơi, xoa bóp và nơi tương tự.",mn:'"Cấm bar, vũ trường, karaoke, sòng bạc".',t:"m",q:"Theo Bộ Luật Lao động, nơi làm việc nào sau đây bị cấm sử dụng người lao động từ đủ 15 tuổi đến chưa đủ 18 tuổi?",o:["Cửa hàng bán lẻ hàng tiêu dùng","Thư viện, nhà sách","Sòng bạc, quán bar, vũ trường, phòng hát karaoke, khách sạn, nhà nghỉ, cơ sở tắm hơi, xoa bóp","Trung tâm dạy nghề"],c:2},{id:"vb14-120",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 148",gt:"Người lao động cao tuổi là người tiếp tục lao động sau độ tuổi nghỉ hưu theo quy định.",mn:'"Làm tiếp sau tuổi hưu".',t:"m",q:"Theo Bộ Luật Lao động, người lao động cao tuổi được xác định là người như thế nào?",o:["Người từ đủ 55 tuổi trở lên đối với mọi giới","Người đã nghỉ hưu và không còn làm việc","Người từ đủ 50 tuổi làm nghề nặng nhọc","Người tiếp tục lao động sau độ tuổi nghỉ hưu theo quy định"],c:3},{id:"vb14-121",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 151",gt:"Lao động nước ngoài phải đủ 18 tuổi trở lên, có năng lực hành vi dân sự đầy đủ và có giấy phép lao động (trừ trường hợp được miễn).",mn:'"Đủ 18, có giấy phép lao động".',t:"m",q:"Theo Bộ Luật Lao động, một trong các điều kiện bắt buộc để người lao động nước ngoài làm việc tại Việt Nam (ngoài các trường hợp miễn) là gì?",o:["Đủ 18 tuổi trở lên, có năng lực hành vi dân sự đầy đủ và có giấy phép lao động do cơ quan có thẩm quyền của Việt Nam cấp","Chỉ cần có hộ chiếu còn hạn và hợp đồng lao động","Được doanh nghiệp bảo lãnh, không cần giấy phép lao động","Cư trú tại Việt Nam từ 06 tháng trở lên"],c:0},{id:"vb14-122",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 155",gt:"Giấy phép lao động tối đa 02 năm; gia hạn chỉ một lần, thời hạn tối đa 02 năm.",mn:'"2 năm, gia hạn 1 lần".',t:"m",q:"Theo Bộ Luật Lao động, thời hạn của giấy phép lao động cấp cho người lao động nước ngoài được quy định như thế nào?",o:["Tối đa 03 năm; được gia hạn nhiều lần","Tối đa 02 năm; trường hợp gia hạn thì chỉ được gia hạn một lần với thời hạn tối đa 02 năm","Tối đa 05 năm; gia hạn theo hợp đồng","Tối đa 01 năm; gia hạn hai lần"],c:1},{id:"vb14-123",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 153",gt:"Lao động nước ngoài không có giấy phép lao động bị buộc xuất cảnh hoặc trục xuất; người sử dụng lao động dùng lao động không phép cũng bị xử lý.",mn:'"Không phép: buộc xuất cảnh, trục xuất".',t:"m",q:"Theo Bộ Luật Lao động, người lao động nước ngoài làm việc tại Việt Nam mà không có giấy phép lao động sẽ bị xử lý ra sao?",o:["Bị phạt tiền và tiếp tục được làm việc","Bị tạm giữ giấy tờ tùy thân đến khi hoàn thiện hồ sơ","Bị buộc xuất cảnh hoặc trục xuất theo quy định của pháp luật","Được gia hạn thời gian bổ sung giấy phép"],c:2},{id:"vb14-124",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 160",gt:"Cấm dùng người khuyết tật nặng, đặc biệt nặng hoặc suy giảm khả năng lao động từ 51% trở lên làm thêm giờ, làm ban đêm, trừ khi họ đồng ý.",mn:'"Khuyết tật ≥51%: cấm làm thêm trừ khi đồng ý".',t:"m",q:"Theo Bộ Luật Lao động, việc sử dụng người lao động là người khuyết tật làm thêm giờ, làm việc ban đêm được quy định thế nào đối với người khuyết tật nặng hoặc suy giảm khả năng lao động từ 51% trở lên?",o:["Được sử dụng bình thường như lao động khác","Chỉ cấm làm việc ban đêm, được làm thêm giờ","Cấm tuyệt đối, không có ngoại lệ","Cấm sử dụng làm thêm giờ, làm việc ban đêm, trừ trường hợp người khuyết tật đồng ý"],c:3},{id:"vb14-125",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 162",gt:"Với người giúp việc gia đình, phải giao kết hợp đồng lao động bằng văn bản.",mn:'"Giúp việc: hợp đồng bằng văn bản".',t:"m",q:"Theo Bộ Luật Lao động, hình thức giao kết hợp đồng lao động đối với lao động là người giúp việc gia đình được quy định như thế nào?",o:["Phải giao kết hợp đồng lao động bằng văn bản","Được giao kết bằng lời nói do hai bên tự thỏa thuận","Không bắt buộc phải giao kết hợp đồng","Chỉ cần đăng ký tại Ủy ban nhân dân cấp xã"],c:0},{id:"vb14-126",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 162",gt:"Một bên có thể đơn phương chấm dứt hợp đồng lao động bất kỳ khi nào nhưng phải báo trước ít nhất 15 ngày.",mn:'"Giúp việc: báo trước 15 ngày".',t:"m",q:"Theo Bộ Luật Lao động, một bên trong quan hệ lao động với người giúp việc gia đình có quyền đơn phương chấm dứt hợp đồng lao động bất kỳ khi nào nhưng phải báo trước ít nhất bao lâu?",o:["Ít nhất 30 ngày","Ít nhất 15 ngày","Ít nhất 45 ngày","Ít nhất 03 ngày"],c:1},{id:"vb14-127",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 165",gt:"Nghiêm cấm giữ giấy tờ tùy thân của người giúp việc, cùng với ngược đãi, quấy rối, cưỡng bức, dùng vũ lực.",mn:'"Cấm giữ giấy tờ tùy thân".',t:"m",q:"Theo Bộ Luật Lao động, hành vi nào sau đây bị nghiêm cấm đối với người sử dụng lao động khi sử dụng lao động là người giúp việc gia đình?",o:["Yêu cầu người lao động nấu ăn, dọn dẹp","Trả lương theo tháng","Giữ giấy tờ tùy thân của người lao động","Bố trí chỗ ở tại nhà chủ"],c:2},{id:"vb14-128",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 168",gt:"Người sử dụng lao động và người lao động phải tham gia BHXH bắt buộc, BHYT, BHTN; được hưởng chế độ theo pháp luật liên quan.",mn:'"Bắt buộc: BHXH – BHYT – BHTN".',t:"m",q:"Theo Bộ Luật Lao động, nghĩa vụ tham gia bảo hiểm của người sử dụng lao động và người lao động được quy định như thế nào?",o:["Chỉ khuyến khích tham gia bảo hiểm xã hội tự nguyện","Chỉ bắt buộc tham gia bảo hiểm y tế","Do người lao động tự quyết định tham gia","Phải tham gia bảo hiểm xã hội bắt buộc, bảo hiểm y tế, bảo hiểm thất nghiệp"],c:3},{id:"vb14-129",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 169",gt:"Lộ trình đến đủ 62 tuổi với nam vào năm 2028 và đủ 60 tuổi với nữ vào năm 2035.",mn:'"Nam 62 (2028), nữ 60 (2035)".',t:"m",q:"Theo Bộ Luật Lao động, lộ trình điều chỉnh tuổi nghỉ hưu trong điều kiện lao động bình thường hướng đến mốc nào?",o:["Đủ 62 tuổi đối với lao động nam vào năm 2028 và đủ 60 tuổi đối với lao động nữ vào năm 2035","Đủ 60 tuổi với nam và 55 tuổi với nữ ngay từ năm 2021","Đủ 65 tuổi với nam vào 2030 và 62 tuổi với nữ vào 2035","Đủ 62 tuổi với cả nam và nữ vào năm 2028"],c:0},{id:"vb14-130",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 169",gt:"Có thể nghỉ hưu ở tuổi thấp hơn nhưng không quá 05 tuổi so với tuổi nghỉ hưu bình thường.",mn:'"Sớm nhất không quá 5 tuổi".',t:"m",q:"Theo Bộ Luật Lao động, người lao động bị suy giảm khả năng lao động hoặc làm nghề đặc biệt nặng nhọc, độc hại, nguy hiểm có thể nghỉ hưu ở tuổi thấp hơn nhưng không quá bao nhiêu so với tuổi nghỉ hưu trong điều kiện bình thường?",o:["Không quá 03 tuổi","Không quá 05 tuổi","Không quá 10 tuổi","Không quá 07 tuổi"],c:1},{id:"vb14-131",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 170",gt:"Người lao động có quyền thành lập, gia nhập, hoạt động công đoàn và thành lập, gia nhập tổ chức của người lao động tại doanh nghiệp; hai loại tổ chức bình đẳng.",mn:'"Công đoàn hoặc tổ chức của NLĐ tại DN".',t:"m",q:"Theo Bộ Luật Lao động, người lao động trong doanh nghiệp có các quyền nào về tổ chức đại diện tại cơ sở?",o:["Chỉ được gia nhập công đoàn, không được lập tổ chức khác","Chỉ được lập tổ chức của người lao động tại doanh nghiệp","Thành lập, gia nhập, hoạt động công đoàn theo Luật Công đoàn và thành lập, gia nhập tổ chức của người lao động tại doanh nghiệp","Không được tham gia bất kỳ tổ chức đại diện nào"],c:2},{id:"vb14-132",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 172",gt:"Tổ chức của người lao động tại doanh nghiệp hoạt động hợp pháp sau khi được cấp đăng ký, bảo đảm tự nguyện, tự quản, dân chủ, minh bạch.",mn:'"Hợp pháp khi được cấp đăng ký".',t:"m",q:"Theo Bộ Luật Lao động, tổ chức của người lao động tại doanh nghiệp được thành lập và hoạt động hợp pháp khi nào?",o:["Ngay khi có đủ số thành viên tối thiểu","Sau khi thông báo cho người sử dụng lao động","Khi được đại hội công nhân thông qua","Sau khi cơ quan nhà nước có thẩm quyền cấp đăng ký"],c:3},{id:"vb14-133",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 173",gt:"Thành viên ban lãnh đạo phải là người lao động Việt Nam đang làm việc tại doanh nghiệp, không đang bị truy cứu, chấp hành hình phạt hoặc chưa xóa án tích với một số tội.",mn:'"Người Việt Nam đang làm việc tại DN".',t:"m",q:"Theo Bộ Luật Lao động, thành viên ban lãnh đạo của tổ chức của người lao động tại doanh nghiệp phải đáp ứng yêu cầu nào?",o:["Là người lao động Việt Nam đang làm việc tại doanh nghiệp và không đang bị truy cứu trách nhiệm hình sự, chưa được xóa án tích với một số tội","Là người lao động bất kỳ, kể cả người nước ngoài","Là cán bộ công đoàn cấp trên biệt phái","Do người sử dụng lao động chỉ định"],c:0},{id:"vb14-134",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 177",gt:"Phải báo cáo cơ quan chuyên môn về lao động thuộc Ủy ban nhân dân cấp tỉnh; sau 30 ngày kể từ ngày báo, người sử dụng lao động mới có quyền quyết định.",mn:'"Báo cơ quan LĐ cấp tỉnh, chờ 30 ngày".',t:"m",q:"Theo Bộ Luật Lao động, khi không thỏa thuận được với ban lãnh đạo tổ chức đại diện về việc kỷ luật sa thải, đơn phương chấm dứt hợp đồng với thành viên ban lãnh đạo, người sử dụng lao động phải báo cáo cơ quan nào và sau bao lâu mới có quyền quyết định?",o:["Báo cáo tổ chức công đoàn cấp trên và sau 15 ngày","Báo cáo cơ quan chuyên môn về lao động thuộc Ủy ban nhân dân cấp tỉnh và sau 30 ngày mới có quyền quyết định","Báo cáo Ủy ban nhân dân cấp xã và sau 10 ngày","Báo cáo Tòa án nhân dân và chờ phán quyết"],c:1},{id:"vb14-135",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 178",gt:"Tổ chức đại diện được thương lượng tập thể, đối thoại tại nơi làm việc, tổ chức và lãnh đạo đình công theo quy định.",mn:'"Thương lượng – đối thoại – lãnh đạo đình công".',t:"m",q:"Theo Bộ Luật Lao động, tổ chức đại diện người lao động tại cơ sở có quyền và nghĩa vụ nào trong quan hệ lao động?",o:["Ban hành nội quy lao động thay người sử dụng lao động","Quyết định mức lương tối thiểu vùng","Thương lượng tập thể, đối thoại tại nơi làm việc và tổ chức, lãnh đạo đình công theo quy định","Cấp phép hoạt động cho doanh nghiệp"],c:2},{id:"vb14-136",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 179",gt:"Có tranh chấp lao động cá nhân và tranh chấp lao động tập thể về quyền hoặc về lợi ích.",mn:'"Cá nhân và tập thể (quyền/lợi ích)".',t:"m",q:"Theo Bộ Luật Lao động, tranh chấp lao động được phân thành các loại nào?",o:["Chỉ có tranh chấp lao động cá nhân","Tranh chấp về tiền lương và tranh chấp về kỷ luật","Tranh chấp dân sự và tranh chấp hành chính về lao động","Tranh chấp lao động cá nhân và tranh chấp lao động tập thể (về quyền hoặc về lợi ích)"],c:3},{id:"vb14-137",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 184",gt:"Hòa giải viên lao động do Chủ tịch Ủy ban nhân dân cấp tỉnh bổ nhiệm để hòa giải tranh chấp lao động.",mn:'"Chủ tịch UBND tỉnh bổ nhiệm hòa giải viên".',t:"m",q:"Theo Bộ Luật Lao động, hòa giải viên lao động do chủ thể nào bổ nhiệm?",o:["Chủ tịch Ủy ban nhân dân cấp tỉnh","Chủ tịch Ủy ban nhân dân cấp xã","Bộ trưởng Bộ Lao động - Thương binh và Xã hội","Chánh án Tòa án nhân dân cấp tỉnh"],c:0},{id:"vb14-138",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 185",gt:"Chủ tịch Ủy ban nhân dân cấp tỉnh thành lập Hội đồng trọng tài lao động; nhiệm kỳ 05 năm.",mn:'"Chủ tịch UBND tỉnh lập, nhiệm kỳ 5 năm".',t:"m",q:"Theo Bộ Luật Lao động, ai có thẩm quyền quyết định thành lập Hội đồng trọng tài lao động và nhiệm kỳ của Hội đồng là bao lâu?",o:["Bộ trưởng Bộ Lao động - Thương binh và Xã hội; nhiệm kỳ 03 năm","Chủ tịch Ủy ban nhân dân cấp tỉnh quyết định thành lập; nhiệm kỳ 05 năm","Chính phủ; nhiệm kỳ 05 năm","Chủ tịch Ủy ban nhân dân cấp xã; nhiệm kỳ 05 năm"],c:1},{id:"vb14-139",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 185",gt:"Hội đồng trọng tài lao động có ít nhất 15 người, mỗi bên (cơ quan lao động cấp tỉnh, công đoàn cấp tỉnh, tổ chức đại diện người sử dụng lao động) đề cử tối thiểu 05 thành viên.",mn:'"Ít nhất 15, mỗi bên tối thiểu 5".',t:"m",q:"Theo Bộ Luật Lao động, số lượng trọng tài viên lao động của Hội đồng trọng tài lao động được quy định tối thiểu là bao nhiêu?",o:["Ít nhất là 09 người","Ít nhất là 10 người","Ít nhất là 15 người, gồm số lượng ngang nhau do các bên đề cử","Ít nhất là 21 người"],c:2},{id:"vb14-140",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 187",gt:"Thẩm quyền giải quyết tranh chấp cá nhân: hòa giải viên lao động, Hội đồng trọng tài lao động, Tòa án nhân dân.",mn:'"Hòa giải viên – trọng tài – tòa án".',t:"m",q:"Theo Bộ Luật Lao động, các chủ thể nào có thẩm quyền giải quyết tranh chấp lao động cá nhân?",o:["Chỉ Tòa án nhân dân","Ủy ban nhân dân cấp tỉnh và Tòa án","Công đoàn cơ sở và người sử dụng lao động","Hòa giải viên lao động; Hội đồng trọng tài lao động; Tòa án nhân dân"],c:3},{id:"vb14-141",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 188",gt:"Không bắt buộc hòa giải với các tranh chấp như sa thải, đơn phương chấm dứt hợp đồng, bồi thường khi chấm dứt, giúp việc gia đình, BHXH-BHYT-BHTN…",mn:'"Sa thải/đơn phương chấm dứt: bỏ qua hòa giải".',t:"m",q:"Theo Bộ Luật Lao động, tranh chấp lao động cá nhân nào sau đây không bắt buộc phải qua thủ tục hòa giải của hòa giải viên lao động?",o:["Tranh chấp về xử lý kỷ luật lao động theo hình thức sa thải hoặc về trường hợp bị đơn phương chấm dứt hợp đồng lao động","Tranh chấp về mức thưởng cuối năm","Tranh chấp về xếp loại thi đua","Tranh chấp về bố trí ca làm việc"],c:0},{id:"vb14-142",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 190",gt:"Thời hiệu: hòa giải viên 06 tháng, Hội đồng trọng tài 09 tháng, Tòa án 01 năm kể từ ngày phát hiện hành vi vi phạm.",mn:'"Hòa giải 6 tháng – trọng tài 9 tháng – tòa 1 năm".',t:"m",q:"Theo Bộ Luật Lao động, thời hiệu yêu cầu hòa giải viên lao động hòa giải và thời hiệu yêu cầu Tòa án giải quyết tranh chấp lao động cá nhân lần lượt là bao lâu?",o:["Yêu cầu hòa giải viên là 03 tháng; yêu cầu Tòa án là 06 tháng","Yêu cầu hòa giải viên là 06 tháng; yêu cầu Tòa án là 01 năm","Yêu cầu hòa giải viên là 01 năm; yêu cầu Tòa án là 02 năm","Yêu cầu hòa giải viên là 09 tháng; yêu cầu Tòa án là 01 năm"],c:1},{id:"vb14-143",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 198",gt:"Đình công là sự ngừng việc tạm thời, tự nguyện và có tổ chức của người lao động, do tổ chức đại diện có quyền thương lượng tập thể tổ chức và lãnh đạo.",mn:'"Tạm thời – tự nguyện – có tổ chức".',t:"m",q:"Theo Bộ Luật Lao động, đình công được định nghĩa là gì?",o:["Sự ngừng việc do người sử dụng lao động quyết định","Sự nghỉ việc tập thể không cần tổ chức","Sự ngừng việc tạm thời, tự nguyện và có tổ chức của người lao động nhằm đạt được yêu cầu trong quá trình giải quyết tranh chấp lao động","Việc người lao động khiếu nại lên cơ quan nhà nước"],c:2},{id:"vb14-144",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 202",gt:"Ra quyết định đình công khi có trên 50% số người được lấy ý kiến đồng ý.",mn:'"Quá bán (>50%) mới đình công".',t:"m",q:"Theo Bộ Luật Lao động, tổ chức đại diện người lao động ra quyết định đình công bằng văn bản khi kết quả lấy ý kiến đạt tỷ lệ nào?",o:["Khi có từ 2/3 số người lao động đồng ý","Khi có ít nhất 75% số người được lấy ý kiến đồng ý","Khi toàn bộ ban lãnh đạo đồng ý","Khi có trên 50% số người được lấy ý kiến đồng ý"],c:3},{id:"vb14-145",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 202",gt:"Phải gửi văn bản quyết định đình công ít nhất 05 ngày làm việc trước ngày bắt đầu đình công.",mn:'"Báo trước 5 ngày làm việc".',t:"m",q:"Theo Bộ Luật Lao động, trước khi bắt đầu đình công, tổ chức đại diện người lao động phải gửi văn bản quyết định đình công cho người sử dụng lao động và cơ quan liên quan trước ít nhất bao lâu?",o:["Ít nhất 05 ngày làm việc trước ngày bắt đầu đình công","Ít nhất 03 ngày làm việc","Ít nhất 07 ngày làm việc","Ít nhất 10 ngày làm việc"],c:0},{id:"vb14-146",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 204",gt:"Đình công bất hợp pháp gồm: không thuộc trường hợp được đình công, không do tổ chức có quyền lãnh đạo, vi phạm trình tự, thủ tục, khi tranh chấp đang được giải quyết…",mn:'"Sai trình tự là bất hợp pháp".',t:"m",q:"Theo Bộ Luật Lao động, trường hợp nào sau đây là đình công bất hợp pháp?",o:["Được trên 50% người lao động đồng ý","Vi phạm quy định về trình tự, thủ tục tiến hành đình công","Do tổ chức đại diện có quyền lãnh đạo thực hiện đúng trình tự","Đã báo trước đủ 05 ngày làm việc"],c:1},{id:"vb14-147",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 210",gt:"Chủ tịch Ủy ban nhân dân cấp tỉnh quyết định hoãn hoặc ngừng đình công khi có nguy cơ gây thiệt hại nghiêm trọng.",mn:'"Chủ tịch UBND tỉnh hoãn/ngừng đình công".',t:"m",q:"Theo Bộ Luật Lao động, khi xét thấy cuộc đình công có nguy cơ gây thiệt hại nghiêm trọng cho nền kinh tế quốc dân, lợi ích công cộng, quốc phòng, an ninh thì ai có quyền quyết định hoãn hoặc ngừng đình công?",o:["Bộ trưởng Bộ Lao động - Thương binh và Xã hội","Chánh án Tòa án nhân dân cấp tỉnh","Chủ tịch Ủy ban nhân dân cấp tỉnh","Chủ tịch Ủy ban nhân dân cấp xã"],c:2},{id:"vb14-148",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 213",gt:"Chính phủ thống nhất quản lý nhà nước về lao động; Bộ Lao động - Thương binh và Xã hội chịu trách nhiệm trước Chính phủ; Ủy ban nhân dân các cấp quản lý tại địa phương.",mn:'"Chính phủ – Bộ LĐTBXH – UBND các cấp".',t:"m",q:"Theo Bộ Luật Lao động, thẩm quyền quản lý nhà nước về lao động được phân định như thế nào?",o:["Chỉ Bộ Lao động - Thương binh và Xã hội quản lý toàn bộ","Ủy ban nhân dân cấp tỉnh thống nhất quản lý cả nước","Do từng doanh nghiệp tự quản lý","Chính phủ thống nhất quản lý trong cả nước; Bộ Lao động - Thương binh và Xã hội chịu trách nhiệm trước Chính phủ; Ủy ban nhân dân các cấp quản lý tại địa phương"],c:3},{id:"vb14-149",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 216",gt:"Thanh tra đột xuất khi khẩn cấp có nguy cơ đe dọa an toàn, tính mạng, sức khỏe người lao động thì không cần báo trước.",mn:'"Khẩn cấp: thanh tra không báo trước".',t:"m",q:"Theo Bộ Luật Lao động, việc thanh tra đột xuất trong trường hợp khẩn cấp có nguy cơ đe dọa an toàn, tính mạng, sức khỏe, danh dự, nhân phẩm của người lao động tại nơi làm việc được thực hiện như thế nào?",o:["Được thực hiện theo quyết định của người có thẩm quyền mà không cần báo trước","Phải báo trước ít nhất 03 ngày làm việc","Chỉ được thực hiện trong giờ hành chính và có báo trước","Phải được người sử dụng lao động đồng ý"],c:0},{id:"vb14-150",s:"PHẦN I. CÂU HỎI 4 PHƯƠNG ÁN (A/B/C/D)",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 220",gt:"Bộ luật này có hiệu lực từ ngày 01/01/2021; Bộ luật Lao động số 10/2012/QH13 hết hiệu lực kể từ ngày này.",mn:'"Hiệu lực 01/01/2021, thay Luật 2012". nội dung QUY TẮC CHẤM: Mỗi câu có 02 nội dung. Phải chọn Đúng/Sai và đúng kết quả CẢ 02 mới được tính điểm câu đó (sai 1 trong 2 là mất trọn điểm).',t:"m",q:"Theo Bộ Luật Lao động, Bộ luật này có hiệu lực thi hành và Bộ luật Lao động cũ hết hiệu lực như thế nào?",o:["Có hiệu lực từ ngày 01 tháng 7 năm 2021","Có hiệu lực từ ngày 01 tháng 01 năm 2021; Bộ luật Lao động số 10/2012/QH13 hết hiệu lực kể từ ngày Bộ luật này có hiệu lực","Có hiệu lực từ ngày 01 tháng 01 năm 2019","Có hiệu lực từ ngày 01 tháng 01 năm 2020"],c:1},{id:"vb14-151",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 3",gt:"① sai: nội dung mô tả là phân biệt đối xử, còn cưỡng bức lao động là dùng vũ lực, đe dọa hoặc thủ đoạn khác ép làm việc trái ý muốn. ② đúng: độ tuổi lao động tối thiểu là đủ 15 tuổi.",mn:'"Cưỡng bức = ép buộc; phân biệt = loại trừ, ưu tiên".',t:"tf",q:"Xét hai nhận định sau về những quy định chung của pháp luật lao động",st:["Độ tuổi lao động tối thiểu của người lao động là đủ 15 tuổi, trừ một số trường hợp đối với lao động chưa thành niên. ② Cưỡng bức lao động là việc phân biệt, loại trừ hoặc ưu tiên dựa trên giới tính, độ tuổi làm ảnh hưởng đến cơ hội việc làm. ① Cưỡng bức lao động là phân biệt, loại trừ, ưu tiên dựa trên giới tính, độ tuổi.","Độ tuổi lao động tối thiểu là đủ 15 tuổi."],a:[!1,!0]},{id:"vb14-152",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 25 và Điều 26",gt:"① sai: chỉ được thử việc một lần đối với một công việc. ② đúng: lương thử việc ít nhất 85% mức lương công việc.",mn:'"Một công việc, một lần thử, lương 85%".',t:"tf",q:"Xét hai nhận định sau về thử việc",st:["Tiền lương trong thời gian thử việc do hai bên thỏa thuận nhưng ít nhất bằng 85% mức lương của công việc. ② Người sử dụng lao động được thử việc tối đa hai lần đối với cùng một công việc. ① Được thử việc tối đa hai lần đối với một công việc.","Lương thử việc ít nhất bằng 85%."],a:[!1,!0]},{id:"vb14-153",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 14",gt:"① sai: chỉ được giao kết bằng lời nói với hợp đồng dưới 01 tháng. ② đúng: hợp đồng văn bản làm 02 bản, mỗi bên giữ 01 bản.",mn:'"Nói miệng chỉ khi dưới 1 tháng".',t:"tf",q:"Xét hai nhận định sau về hình thức hợp đồng lao động",st:["Hợp đồng lao động bằng văn bản được làm thành 02 bản, mỗi bên giữ 01 bản. ② Hai bên được giao kết hợp đồng lao động bằng lời nói đối với hợp đồng có thời hạn dưới 03 tháng. ① Được giao kết bằng lời nói với hợp đồng dưới 03 tháng.","Hợp đồng văn bản làm 02 bản, mỗi bên giữ 01 bản."],a:[!1,!0]},{id:"vb14-154",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 20 và Điều 22",gt:"① sai: phụ lục không được sửa đổi thời hạn của hợp đồng lao động. ② đúng: hợp đồng xác định thời hạn không quá 36 tháng.",mn:'"Phụ lục sửa mọi thứ, trừ thời hạn".',t:"tf",q:"Xét hai nhận định sau về loại và phụ lục hợp đồng lao động",st:["Hợp đồng lao động xác định thời hạn có thời gian không quá 36 tháng. ② Phụ lục hợp đồng lao động được quyền sửa đổi thời hạn của hợp đồng lao động. ① Phụ lục được sửa đổi thời hạn của hợp đồng.","Hợp đồng xác định thời hạn không quá 36 tháng."],a:[!1,!0]},{id:"vb14-155",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 11 và Điều 12",gt:"① sai: phải khai trình trong 30 ngày kể từ ngày bắt đầu hoạt động. ② đúng: người lao động không phải trả chi phí tuyển dụng.",mn:'"Khai trình 30 ngày, không phải 60".',t:"tf",q:"Xét hai nhận định sau về tuyển dụng và quản lý lao động",st:["Người lao động không phải trả chi phí cho việc tuyển dụng lao động. ② Người sử dụng lao động phải khai trình việc sử dụng lao động trong thời hạn 60 ngày kể từ ngày bắt đầu hoạt động. ① Khai trình sử dụng lao động trong 60 ngày.","Người lao động không phải trả chi phí tuyển dụng."],a:[!1,!0]},{id:"vb14-156",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 46 và Điều 47",gt:"① sai: trợ cấp mất việc làm mỗi năm 01 tháng tiền lương (ít nhất 02 tháng). ② đúng: trợ cấp thôi việc mỗi năm một nửa tháng tiền lương.",mn:'"Thôi việc nửa tháng, mất việc một tháng".',t:"tf",q:"Xét hai nhận định sau về trợ cấp khi chấm dứt hợp đồng lao động",st:["Trợ cấp thôi việc được tính mỗi năm làm việc bằng một nửa tháng tiền lương. ② Trợ cấp mất việc làm được tính mỗi năm làm việc bằng một nửa tháng tiền lương. ① Trợ cấp mất việc làm mỗi năm bằng nửa tháng lương.","Trợ cấp thôi việc mỗi năm bằng nửa tháng lương."],a:[!1,!0]},{id:"vb14-157",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 35",gt:"① sai: hợp đồng dưới 12 tháng chỉ báo trước 03 ngày làm việc. ② đúng: hợp đồng không xác định thời hạn báo trước 45 ngày.",mn:'"Dưới 12 tháng chỉ 3 ngày làm việc".',t:"tf",q:"Xét hai nhận định sau về thời hạn báo trước khi người lao động đơn phương chấm dứt hợp đồng",st:["Với hợp đồng không xác định thời hạn phải báo trước ít nhất 45 ngày. ② Với hợp đồng xác định thời hạn dưới 12 tháng phải báo trước ít nhất 30 ngày. ① Xác định thời hạn dưới 12 tháng: báo trước 30 ngày.","Không xác định thời hạn: báo trước 45 ngày."],a:[!1,!0]},{id:"vb14-158",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 61",gt:"① sai: người học nghề, tập nghề phải đủ 14 tuổi trở lên (nghề độc hại thì từ đủ 18 tuổi). ② đúng: thời hạn tập nghề không quá 03 tháng.",mn:'"Học nghề đủ 14 tuổi, tập nghề 3 tháng".',t:"tf",q:"Xét hai nhận định sau về học nghề, tập nghề",st:["Thời hạn tập nghề để làm việc cho người sử dụng lao động không quá 03 tháng. ② Người học nghề, tập nghề phải đủ 15 tuổi trở lên đối với nghề, công việc thông thường. ① Học nghề, tập nghề phải đủ 15 tuổi trở lên.","Tập nghề không quá 03 tháng."],a:[!1,!0]},{id:"vb14-159",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 29 và Điều 31",gt:"① sai: chỉ được tạm chuyển công việc khác không quá 60 ngày làm việc cộng dồn trong 01 năm. ② đúng: trong 15 ngày kể từ ngày hết tạm hoãn, người lao động phải có mặt.",mn:'"Chuyển việc 60 ngày, trở lại sau tạm hoãn 15 ngày".',t:"tf",q:"Xét hai nhận định sau về chuyển công việc và nhận lại người lao động",st:["Người sử dụng lao động được tạm thời chuyển người lao động làm công việc khác không quá 90 ngày làm việc cộng dồn trong 01 năm nếu không có văn bản đồng ý. ② Trong 15 ngày kể từ ngày hết thời hạn tạm hoãn hợp đồng, người lao động phải có mặt tại nơi làm việc. ① Chuyển công việc khác tối đa 90 ngày/năm.","Hết tạm hoãn: 15 ngày phải có mặt."],a:[!1,!0]},{id:"vb14-160",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 40 và Điều 41",gt:"① sai: người sử dụng lao động phải trả thêm ít nhất 02 tháng tiền lương. ② đúng: người lao động chấm dứt trái pháp luật phải bồi thường nửa tháng tiền lương.",mn:'"NLĐ nửa tháng, NSDLĐ ít nhất 2 tháng".',t:"tf",q:"Xét hai nhận định sau về nghĩa vụ khi đơn phương chấm dứt hợp đồng trái pháp luật",st:["Người lao động chấm dứt trái pháp luật phải bồi thường nửa tháng tiền lương theo hợp đồng. ② Người sử dụng lao động chấm dứt trái pháp luật phải trả thêm ít nhất một tháng tiền lương theo hợp đồng. ① NSDLĐ trái luật: trả thêm ít nhất một tháng lương.","NLĐ trái luật: bồi thường nửa tháng lương."],a:[!1,!0]},{id:"vb14-161",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 50 và Điều 53",gt:"① sai: thời hạn cho thuê lại lao động tối đa là 12 tháng. ② đúng: Tòa án nhân dân có quyền tuyên bố hợp đồng lao động vô hiệu.",mn:'"Thuê lại tối đa 12 tháng, Tòa án tuyên vô hiệu".',t:"tf",q:"Xét hai nhận định sau về hợp đồng lao động vô hiệu và cho thuê lại lao động",st:["Tòa án nhân dân có quyền tuyên bố hợp đồng lao động vô hiệu. ② Thời hạn cho thuê lại lao động đối với người lao động tối đa là 24 tháng. ① Cho thuê lại lao động tối đa 24 tháng.","Tòa án nhân dân tuyên bố hợp đồng vô hiệu."],a:[!1,!0]},{id:"vb14-162",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 9 và Điều 3",gt:"① sai: quan hệ lao động gồm cả cá nhân và tập thể. ② đúng: việc làm là hoạt động lao động tạo thu nhập mà pháp luật không cấm.",mn:'"Quan hệ lao động: cả cá nhân lẫn tập thể".',t:"tf",q:"Xét hai nhận định sau về khái niệm",st:["Việc làm là hoạt động lao động tạo ra thu nhập mà pháp luật không cấm. ② Quan hệ lao động chỉ bao gồm quan hệ lao động cá nhân. ① Quan hệ lao động chỉ gồm quan hệ lao động cá nhân.","Việc làm là hoạt động lao động tạo thu nhập mà pháp luật không cấm."],a:[!1,!0]},{id:"vb14-163",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 36 và Điều 37",gt:"① sai: không được chấm dứt với người nuôi con dưới 12 tháng tuổi. ② đúng: bỏ việc từ 05 ngày làm việc liên tục không lý do chính đáng thì bị đơn phương chấm dứt.",mn:'"Nuôi con dưới 12 tháng được bảo vệ".',t:"tf",q:"Xét hai nhận định sau về đơn phương chấm dứt hợp đồng của người sử dụng lao động",st:["Được đơn phương chấm dứt khi người lao động tự ý bỏ việc không có lý do chính đáng từ 05 ngày làm việc liên tục trở lên. ② Không được đơn phương chấm dứt với người lao động đang nuôi con dưới 24 tháng tuổi. ① Không chấm dứt với người nuôi con dưới 24 tháng.","Bỏ việc 05 ngày làm việc liên tục: bị chấm dứt."],a:[!1,!0]},{id:"vb14-164",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 63",gt:"① sai: còn tổ chức khi có yêu cầu của một hoặc các bên và khi có vụ việc phát sinh, không đòi hỏi cả hai bên cùng yêu cầu. ② đúng: đối thoại phải tổ chức định kỳ ít nhất 01 năm/lần.",mn:'"Định kỳ 1 năm – một bên yêu cầu là đủ".',t:"tf",q:"Xét hai nhận định về đối thoại tại nơi làm việc theo Bộ Luật Lao động",st:["Đối thoại tại nơi làm việc chỉ được tổ chức khi có yêu cầu của cả hai bên.","Người sử dụng lao động phải tổ chức đối thoại tại nơi làm việc định kỳ ít nhất 01 năm một lần."],a:[!1,!0]},{id:"vb14-165",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 76, Điều 78",gt:"① sai: thỏa ước có thời hạn từ 01 năm đến 03 năm, không phải tối đa 05 năm. ② đúng: ký kết khi có trên 50% người lao động tán thành.",mn:'"Trên 50% để ký – thời hạn 1 đến 3 năm".',t:"tf",q:"Xét hai nhận định về thỏa ước lao động tập thể doanh nghiệp theo Bộ Luật Lao động",st:["Thỏa ước lao động tập thể có thời hạn tối đa 05 năm.","Thỏa ước lao động tập thể doanh nghiệp chỉ được ký kết khi có trên 50% người lao động của doanh nghiệp biểu quyết tán thành."],a:[!1,!0]},{id:"vb14-166",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 89, Điều 77",gt:"① sai: phải gửi trong thời hạn 10 ngày, không phải 30 ngày. ② đúng: chi phí do người sử dụng lao động chi trả.",mn:'"Chủ trả chi phí – gửi trong 10 ngày".',t:"tf",q:"Xét hai nhận định về chi phí và việc gửi thỏa ước lao động tập thể theo Bộ Luật Lao động",st:["Người sử dụng lao động phải gửi thỏa ước đã ký đến cơ quan chuyên môn về lao động thuộc Ủy ban nhân dân cấp tỉnh trong thời hạn 30 ngày.","Mọi chi phí thương lượng, ký kết, gửi và công bố thỏa ước lao động tập thể do người sử dụng lao động chi trả."],a:[!1,!0]},{id:"vb14-167",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 98",gt:"① sai: làm thêm ngày nghỉ lễ, tết phải ít nhất 300% (chưa kể tiền lương ngày lễ, tết). ② đúng: làm thêm ngày nghỉ hằng tuần ít nhất 200%.",mn:'"Nghỉ tuần 200% – lễ tết 300%".',t:"tf",q:"Xét hai nhận định về tiền lương làm thêm giờ theo Bộ Luật Lao động",st:["Làm thêm giờ vào ngày nghỉ lễ, tết được trả lương ít nhất bằng 200%.","Làm thêm giờ vào ngày nghỉ hằng tuần được trả lương ít nhất bằng 200%."],a:[!1,!0]},{id:"vb14-168",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 102, Điều 98",gt:"① sai: làm việc ban đêm được trả thêm ít nhất 30% (không phải 20%). ② đúng: khấu trừ không quá 30%/tháng.",mn:'"Khấu trừ ≤30% – ban đêm thêm ≥30%".',t:"tf",q:"Xét hai nhận định về khấu trừ và làm việc ban đêm theo Bộ Luật Lao động",st:["Người lao động làm việc vào ban đêm được trả thêm ít nhất bằng 20% tiền lương của công việc ngày làm việc bình thường.","Mức khấu trừ tiền lương hằng tháng không được quá 30% tiền lương thực trả sau khi trích nộp các khoản bảo hiểm bắt buộc và thuế thu nhập cá nhân."],a:[!1,!0]},{id:"vb14-169",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 99",gt:"① sai: ngừng việc do lỗi của người lao động thì người đó không được trả lương. ② đúng: lỗi của chủ thì trả đủ lương.",mn:'"Lỗi chủ: trả đủ – lỗi thợ: không lương".',t:"tf",q:"Xét hai nhận định về tiền lương ngừng việc theo Bộ Luật Lao động",st:["Ngừng việc do lỗi của người lao động thì người lao động đó vẫn được trả đủ tiền lương theo hợp đồng.","Ngừng việc do lỗi của người sử dụng lao động thì người lao động được trả đủ tiền lương theo hợp đồng lao động."],a:[!1,!0]},{id:"vb14-170",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 105, Điều 107",gt:"① đúng: bình thường 8 giờ/ngày – 48 giờ/tuần. ② sai: 40 giờ là giới hạn trong 01 tháng; trong 01 năm là không quá 200 giờ (đặc biệt 300 giờ).",mn:'"48 giờ/tuần – 40 giờ/tháng, 200 giờ/năm".',t:"tf",q:"Xét hai nhận định về thời giờ làm việc và làm thêm giờ theo Bộ Luật Lao động",st:["Thời giờ làm việc bình thường không quá 08 giờ trong 01 ngày và không quá 48 giờ trong 01 tuần.","Số giờ làm thêm của người lao động không được quá 40 giờ trong 01 năm."],a:[!0,!1]},{id:"vb14-171",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 109, Điều 110",gt:"① đúng: làm ban đêm nghỉ giữa giờ ít nhất 45 phút. ② sai: nghỉ chuyển ca phải ít nhất 12 giờ (không phải 8 giờ).",mn:'"Ban đêm nghỉ 45 phút – chuyển ca 12 giờ".',t:"tf",q:"Xét hai nhận định về nghỉ giữa giờ và nghỉ chuyển ca theo Bộ Luật Lao động",st:["Làm việc ban đêm thì được nghỉ giữa giờ ít nhất 45 phút liên tục.","Người lao động làm việc theo ca được nghỉ ít nhất 08 giờ trước khi chuyển sang ca khác."],a:[!0,!1]},{id:"vb14-172",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 113, Điều 114",gt:"① đúng: điều kiện bình thường nghỉ 12 ngày. ② sai: cứ đủ 05 năm mới được tăng thêm 01 ngày nghỉ theo thâm niên (không phải 03 năm).",mn:'"12 ngày cơ bản – thâm niên 5 năm thêm 1 ngày".',t:"tf",q:"Xét hai nhận định về nghỉ hằng năm theo Bộ Luật Lao động",st:["Người làm công việc trong điều kiện bình thường đủ 12 tháng được nghỉ hằng năm 12 ngày làm việc.","Cứ đủ 03 năm làm việc cho một người sử dụng lao động thì số ngày nghỉ hằng năm được tăng thêm 01 ngày."],a:[!0,!1]},{id:"vb14-173",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 118, Điều 121",gt:"① đúng: từ 10 lao động trở lên phải có nội quy bằng văn bản. ② sai: nội quy có hiệu lực sau 15 ngày kể từ ngày cơ quan có thẩm quyền nhận đủ hồ sơ đăng ký.",mn:'"≥10: văn bản – hiệu lực sau 15 ngày".',t:"tf",q:"Xét hai nhận định về nội quy lao động theo Bộ Luật Lao động",st:["Người sử dụng lao động sử dụng từ 10 người lao động trở lên thì nội quy lao động phải bằng văn bản.","Nội quy lao động có hiệu lực ngay khi người sử dụng lao động ban hành."],a:[!0,!1]},{id:"vb14-174",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 123, Điều 122",gt:"① đúng: thời hiệu thông thường 06 tháng (tài chính, bí mật là 12 tháng). ② sai: không được áp dụng nhiều hình thức kỷ luật cho một hành vi vi phạm.",mn:'"Thời hiệu 6 tháng – một hành vi một hình thức".',t:"tf",q:"Xét hai nhận định về xử lý kỷ luật lao động theo Bộ Luật Lao động",st:["Thời hiệu xử lý kỷ luật lao động thông thường là 06 tháng kể từ ngày xảy ra hành vi vi phạm.","Được áp dụng nhiều hình thức xử lý kỷ luật lao động đối với một hành vi vi phạm."],a:[!0,!1]},{id:"vb14-175",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 128",gt:"① đúng: tạm đình chỉ không quá 15 ngày, đặc biệt không quá 90 ngày. ② sai: được tạm ứng 50% tiền lương (không phải 70%).",mn:'"15/90 ngày – tạm ứng 50%".',t:"tf",q:"Xét hai nhận định về tạm đình chỉ công việc theo Bộ Luật Lao động",st:["Thời hạn tạm đình chỉ công việc thông thường không được quá 15 ngày, trường hợp đặc biệt không quá 90 ngày.","Trong thời gian bị tạm đình chỉ công việc, người lao động được tạm ứng 70% tiền lương."],a:[!0,!1]},{id:"vb14-176",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 133",gt:"① đúng: Chính phủ quyết định chương trình quốc gia. ② sai: UBND cấp tỉnh phải trình Hội đồng nhân dân cùng cấp quyết định chương trình của địa phương.",mn:'"Quốc gia: Chính phủ – địa phương: trình HĐND".',t:"tf",q:"Xét hai nhận định về chương trình an toàn, vệ sinh lao động theo Bộ Luật Lao động",st:["Chính phủ quyết định Chương trình quốc gia về an toàn, vệ sinh lao động.","Ủy ban nhân dân cấp tỉnh tự quyết định Chương trình an toàn, vệ sinh lao động của địa phương mà không cần trình Hội đồng nhân dân."],a:[!0,!1]},{id:"vb14-177",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 137",gt:"① đúng: hành kinh nghỉ 30 phút/ngày. ② đúng: nuôi con dưới 12 tháng nghỉ 60 phút/ngày, đều hưởng đủ lương.",mn:'"Hành kinh 30 phút, nuôi con nhỏ 60 phút".',t:"tf",q:"Theo Bộ Luật Lao động, xét hai nhận định về chế độ nghỉ trong giờ làm việc của lao động nữ.",st:["Trong thời gian hành kinh, lao động nữ được nghỉ mỗi ngày 30 phút.","Trong thời gian nuôi con dưới 12 tháng tuổi, lao động nữ được nghỉ mỗi ngày 60 phút."],a:[!0,!0]},{id:"vb14-178",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 139",gt:"① đúng: nghỉ thai sản 06 tháng. ② sai: thời gian nghỉ trước khi sinh không quá 02 tháng, không phải 03 tháng.",mn:'"6 tháng, trước sinh ≤ 2 tháng".',t:"tf",q:"Theo Bộ Luật Lao động, xét hai nhận định về nghỉ thai sản của lao động nữ.",st:["Lao động nữ được nghỉ thai sản trước và sau khi sinh con là 06 tháng.","Thời gian nghỉ trước khi sinh không quá 03 tháng."],a:[!0,!1]},{id:"vb14-179",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 146",gt:"① đúng: không quá 04 giờ/ngày (và 20 giờ/tuần). ② sai: người chưa đủ 15 tuổi không được làm thêm giờ, làm việc ban đêm.",mn:'"4 giờ/ngày, cấm làm thêm".',t:"tf",q:"Theo Bộ Luật Lao động, xét hai nhận định về thời giờ làm việc của người chưa đủ 15 tuổi.",st:["Thời giờ làm việc không được quá 04 giờ trong 01 ngày.","Người chưa đủ 15 tuổi được làm thêm giờ nếu có sự đồng ý của cha mẹ."],a:[!0,!1]},{id:"vb14-180",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 155",gt:"① đúng: thời hạn giấy phép lao động tối đa 02 năm. ② sai: chỉ được gia hạn một lần, tối đa 02 năm.",mn:'"2 năm, gia hạn duy nhất 1 lần".',t:"tf",q:"Theo Bộ Luật Lao động, xét hai nhận định về giấy phép lao động của người nước ngoài.",st:["Thời hạn của giấy phép lao động tối đa là 02 năm.","Giấy phép lao động được gia hạn nhiều lần không giới hạn."],a:[!0,!1]},{id:"vb14-181",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 162, 165",gt:"① đúng: phải giao kết hợp đồng bằng văn bản. ② sai: nghiêm cấm giữ giấy tờ tùy thân của người lao động.",mn:'"Văn bản: có; giữ giấy tờ: cấm".',t:"tf",q:"Theo Bộ Luật Lao động, xét hai nhận định về lao động là người giúp việc gia đình.",st:["Người sử dụng lao động phải giao kết hợp đồng lao động bằng văn bản với người giúp việc gia đình.","Người sử dụng lao động được giữ giấy tờ tùy thân của người giúp việc để bảo đảm."],a:[!0,!1]},{id:"vb14-182",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 169",gt:"① đúng: nam đủ 62 tuổi vào năm 2028. ② sai: nữ đủ 60 tuổi vào năm 2035, không phải 2030.",mn:'"Nam 62 (2028), nữ 60 (2035)".',t:"tf",q:"Theo Bộ Luật Lao động, xét hai nhận định về lộ trình tuổi nghỉ hưu trong điều kiện lao động bình thường.",st:["Tuổi nghỉ hưu của lao động nam được điều chỉnh đến đủ 62 tuổi vào năm 2028.","Tuổi nghỉ hưu của lao động nữ được điều chỉnh đến đủ 60 tuổi vào năm 2030."],a:[!0,!1]},{id:"vb14-183",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 173",gt:"① đúng: thành viên ban lãnh đạo là người lao động Việt Nam đang làm việc tại doanh nghiệp. ② sai: không quy định cho người nước ngoài.",mn:'"Ban lãnh đạo: người Việt Nam".',t:"tf",q:"Theo Bộ Luật Lao động, xét hai nhận định về thành viên ban lãnh đạo tổ chức của người lao động tại doanh nghiệp.",st:["Thành viên ban lãnh đạo là người lao động Việt Nam đang làm việc tại doanh nghiệp.","Người lao động nước ngoài đang làm việc tại doanh nghiệp có thể làm thành viên ban lãnh đạo."],a:[!0,!1]},{id:"vb14-184",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 185",gt:"① đúng: nhiệm kỳ 05 năm. ② sai: số lượng trọng tài viên ít nhất là 15 người, không phải 10.",mn:'"Nhiệm kỳ 5 năm, tối thiểu 15 người".',t:"tf",q:"Theo Bộ Luật Lao động, xét hai nhận định về Hội đồng trọng tài lao động.",st:["Nhiệm kỳ của Hội đồng trọng tài lao động là 05 năm.","Số lượng trọng tài viên lao động của Hội đồng ít nhất là 10 người."],a:[!0,!1]},{id:"vb14-185",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 190",gt:"① đúng: yêu cầu Tòa án là 01 năm. ② sai: yêu cầu hòa giải viên là 06 tháng, không phải 03 tháng.",mn:'"Tòa 1 năm, hòa giải viên 6 tháng".',t:"tf",q:"Theo Bộ Luật Lao động, xét hai nhận định về thời hiệu yêu cầu giải quyết tranh chấp lao động cá nhân.",st:["Thời hiệu yêu cầu Tòa án giải quyết tranh chấp lao động cá nhân là 01 năm.","Thời hiệu yêu cầu hòa giải viên lao động hòa giải là 03 tháng."],a:[!0,!1]},{id:"vb14-186",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 202",gt:"① đúng: trên 50% đồng ý mới ra quyết định. ② sai: phải gửi văn bản ít nhất 05 ngày làm việc trước ngày bắt đầu đình công.",mn:'"Quá bán; báo trước 5 ngày làm việc".',t:"tf",q:"Theo Bộ Luật Lao động, xét hai nhận định về trình tự, điều kiện đình công.",st:["Tổ chức đại diện ra quyết định đình công khi có trên 50% số người được lấy ý kiến đồng ý.","Phải gửi văn bản quyết định đình công cho người sử dụng lao động ít nhất 03 ngày làm việc trước khi bắt đầu."],a:[!0,!1]},{id:"vb14-187",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 213",gt:"① đúng: Chính phủ thống nhất quản lý cả nước. ② đúng: Ủy ban nhân dân các cấp quản lý tại địa phương.",mn:'"Chính phủ cả nước – UBND địa phương".',t:"tf",q:"Theo Bộ Luật Lao động, xét hai nhận định về thẩm quyền quản lý nhà nước về lao động.",st:["Chính phủ thống nhất quản lý nhà nước về lao động trong phạm vi cả nước.","Ủy ban nhân dân các cấp thực hiện quản lý nhà nước về lao động trong phạm vi địa phương mình."],a:[!0,!0]},{id:"vb14-188",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 216",gt:"① đúng: trường hợp khẩn cấp thì không cần báo trước. ② sai: không phải mọi trường hợp đều bắt buộc báo trước.",mn:'"Khẩn cấp thì miễn báo trước".',t:"tf",q:"Theo Bộ Luật Lao động, xét hai nhận định về thanh tra lao động.",st:["Thanh tra đột xuất khi khẩn cấp có nguy cơ đe dọa an toàn, tính mạng người lao động thì không cần báo trước.","Thanh tra lao động chỉ được tiến hành thanh tra sau khi báo trước cho người sử dụng lao động trong mọi trường hợp."],a:[!0,!1]},{id:"vb14-189",s:"PHẦN II. CÂU ĐÚNG/SAI – 2 NỘI DUNG TRONG 1 CÂU",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 218, 220",gt:"① đúng: dùng dưới 10 lao động được miễn, giảm một số thủ tục. ② sai: Bộ luật có hiệu lực từ 01/01/2021, không phải 2020.",mn:'"Dưới 10 lao động: giảm thủ tục; hiệu lực 2021".',t:"tf",q:"Theo Bộ Luật Lao động, xét hai nhận định về điều khoản thi hành.",st:["Người sử dụng lao động sử dụng dưới 10 người lao động được miễn, giảm một số thủ tục theo quy định của Chính phủ.","Bộ luật này có hiệu lực thi hành từ ngày 01 tháng 01 năm 2020."],a:[!0,!1]},{id:"vb14-190",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 3",gt:"Độ tuổi lao động tối thiểu là đủ 15 tuổi.",mn:'"Đủ 15 tuổi".',t:"f",q:"Theo Bộ Luật Lao động, độ tuổi lao động tối thiểu của người lao động là …………………, trừ một số trường hợp đối với lao động chưa thành niên.",ans:"đủ 15 tuổi"},{id:"vb14-191",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 3",gt:"Đó là hành vi cưỡng bức lao động.",mn:'"Ép làm trái ý muốn".',t:"f",q:"Theo Bộ Luật Lao động, việc dùng vũ lực, đe dọa dùng vũ lực hoặc các thủ đoạn khác để ép buộc người lao động phải làm việc trái ý muốn của họ được gọi là …………………",ans:"cưỡng bức lao động"},{id:"vb14-192",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 9",gt:"Khái niệm việc làm gắn với tạo thu nhập và không bị cấm.",mn:'"Tạo thu nhập, không bị cấm".',t:"f",q:"Theo Bộ Luật Lao động, hoạt động lao động tạo ra thu nhập mà pháp luật không cấm được gọi là …………………",ans:"việc làm"},{id:"vb14-193",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 12",gt:"Thời hạn khai trình là 30 ngày kể từ ngày bắt đầu hoạt động.",mn:'"Bắt đầu hoạt động: 30 ngày".',t:"f",q:"Theo Bộ Luật Lao động, người sử dụng lao động phải khai trình việc sử dụng lao động trong thời hạn ………………… kể từ ngày bắt đầu hoạt động.",ans:"30 ngày"},{id:"vb14-194",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 11",gt:"Người lao động không phải trả chi phí tuyển dụng.",mn:'"Tuyển dụng miễn phí cho NLĐ".',t:"f",q:"Theo Bộ Luật Lao động, người lao động ………………… cho việc tuyển dụng lao động.",ans:"không phải trả chi phí"},{id:"vb14-195",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 14",gt:"Hợp đồng văn bản làm thành 02 bản.",mn:'"Hai bản, mỗi bên một bản".',t:"f",q:"Theo Bộ Luật Lao động, hợp đồng lao động giao kết bằng văn bản được làm thành …………………, người lao động giữ 01 bản, người sử dụng lao động giữ 01 bản.",ans:"02 bản"},{id:"vb14-196",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 14",gt:"Chỉ giao kết bằng lời nói với hợp đồng dưới 01 tháng.",mn:'"Dưới 1 tháng mới nói miệng".',t:"f",q:"Theo Bộ Luật Lao động, hai bên có thể giao kết hợp đồng lao động bằng lời nói đối với hợp đồng có thời hạn …………………",ans:"dưới 01 tháng"},{id:"vb14-197",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 20",gt:"Hợp đồng xác định thời hạn không quá 36 tháng.",mn:'"Tối đa 36 tháng".',t:"f",q:"Theo Bộ Luật Lao động, hợp đồng lao động xác định thời hạn là hợp đồng mà hai bên xác định thời hạn, thời điểm chấm dứt hiệu lực trong thời gian …………………",ans:"không quá 36 tháng"},{id:"vb14-198",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 20",gt:"Phải ký hợp đồng mới trong 30 ngày kể từ ngày hết hạn.",mn:'"Hết hạn: 30 ngày ký mới".',t:"f",q:"Theo Bộ Luật Lao động, trong thời hạn ………………… kể từ ngày hợp đồng lao động xác định thời hạn hết hạn mà người lao động tiếp tục làm việc, hai bên phải ký kết hợp đồng lao động mới.",ans:"30 ngày"},{id:"vb14-199",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 25",gt:"Thử việc với người quản lý doanh nghiệp tối đa 180 ngày.",mn:'"Quản lý doanh nghiệp: 180 ngày".',t:"f",q:"Theo Bộ Luật Lao động, thời gian thử việc đối với công việc của người quản lý doanh nghiệp là không quá …………………",ans:"180 ngày"},{id:"vb14-200",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 25",gt:"Thử việc với công việc cần trình độ cao đẳng trở lên tối đa 60 ngày.",mn:'"Cao đẳng trở lên: 60 ngày".',t:"f",q:"Theo Bộ Luật Lao động, thời gian thử việc đối với công việc cần trình độ chuyên môn, kỹ thuật từ cao đẳng trở lên là không quá …………………",ans:"60 ngày"},{id:"vb14-201",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 25",gt:"Thử việc với công việc cần trình độ trung cấp tối đa 30 ngày.",mn:'"Trung cấp: 30 ngày".',t:"f",q:"Theo Bộ Luật Lao động, thời gian thử việc đối với công việc cần trình độ trung cấp, công nhân kỹ thuật, nhân viên nghiệp vụ là không quá …………………",ans:"30 ngày"},{id:"vb14-202",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 25",gt:"Thử việc với công việc khác tối đa 06 ngày làm việc.",mn:'"Việc khác: 6 ngày làm việc".',t:"f",q:"Theo Bộ Luật Lao động, thời gian thử việc đối với công việc khác là không quá …………………",ans:"06 ngày làm việc"},{id:"vb14-203",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 26",gt:"Lương thử việc ít nhất 85% mức lương công việc.",mn:'"Thử việc: tối thiểu 85%".',t:"f",q:"Theo Bộ Luật Lao động, tiền lương của người lao động trong thời gian thử việc do hai bên thỏa thuận nhưng ít nhất phải bằng ………………… mức lương của công việc đó.",ans:"85%"},{id:"vb14-204",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 29",gt:"Tạm chuyển công việc khác không quá 60 ngày làm việc cộng dồn/năm.",mn:'"Chuyển việc: 60 ngày/năm".',t:"f",q:"Theo Bộ Luật Lao động, người sử dụng lao động được tạm thời chuyển người lao động làm công việc khác so với hợp đồng nhưng không được quá ………………… cộng dồn trong 01 năm, nếu không có văn bản đồng ý của người lao động.",ans:"60 ngày làm việc"},{id:"vb14-205",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 29",gt:"Phải báo trước ít nhất 03 ngày làm việc.",mn:'"Chuyển việc: báo trước 3 ngày làm việc".',t:"f",q:"Theo Bộ Luật Lao động, khi tạm thời chuyển người lao động làm công việc khác, người sử dụng lao động phải báo trước cho người lao động ít nhất …………………",ans:"03 ngày làm việc"},{id:"vb14-206",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 29",gt:"Giữ nguyên lương cũ trong 30 ngày làm việc.",mn:'"Giữ lương cũ 30 ngày làm việc".',t:"f",q:"Theo Bộ Luật Lao động, khi chuyển sang công việc mới có lương thấp hơn, người lao động được giữ nguyên tiền lương của công việc cũ trong thời hạn …………………",ans:"30 ngày làm việc"},{id:"vb14-207",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 31",gt:"Trong 15 ngày kể từ ngày hết tạm hoãn, người lao động phải có mặt.",mn:'"Hết tạm hoãn: 15 ngày".',t:"f",q:"Theo Bộ Luật Lao động, trong thời hạn ………………… kể từ ngày hết thời hạn tạm hoãn thực hiện hợp đồng lao động, người lao động phải có mặt tại nơi làm việc.",ans:"15 ngày"},{id:"vb14-208",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 33",gt:"Phải báo trước ít nhất 03 ngày làm việc về nội dung cần sửa đổi.",mn:'"Sửa hợp đồng: 3 ngày làm việc".',t:"f",q:"Theo Bộ Luật Lao động, khi có yêu cầu sửa đổi, bổ sung nội dung hợp đồng lao động, bên yêu cầu phải báo cho bên kia biết trước ít nhất …………………",ans:"03 ngày làm việc"},{id:"vb14-209",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 35",gt:"Hợp đồng không xác định thời hạn báo trước 45 ngày.",mn:'"Không xác định thời hạn: 45 ngày".',t:"f",q:"Theo Bộ Luật Lao động, người lao động làm việc theo hợp đồng lao động không xác định thời hạn khi đơn phương chấm dứt phải báo trước ít nhất …………………",ans:"45 ngày"},{id:"vb14-210",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 35",gt:"Hợp đồng 12–36 tháng báo trước 30 ngày.",mn:'"12–36 tháng: 30 ngày".',t:"f",q:"Theo Bộ Luật Lao động, người lao động làm việc theo hợp đồng lao động xác định thời hạn từ 12 tháng đến 36 tháng khi đơn phương chấm dứt phải báo trước ít nhất …………………",ans:"30 ngày"},{id:"vb14-211",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 35",gt:"Hợp đồng dưới 12 tháng báo trước 03 ngày làm việc.",mn:'"Dưới 12 tháng: 3 ngày làm việc".',t:"f",q:"Theo Bộ Luật Lao động, người lao động làm việc theo hợp đồng lao động xác định thời hạn dưới 12 tháng khi đơn phương chấm dứt phải báo trước ít nhất …………………",ans:"03 ngày làm việc"},{id:"vb14-212",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 36",gt:"Bỏ việc từ 05 ngày làm việc liên tục trở lên thì bị đơn phương chấm dứt.",mn:'"Bỏ việc 5 ngày liên tục".',t:"f",q:"Theo Bộ Luật Lao động, người sử dụng lao động được đơn phương chấm dứt hợp đồng khi người lao động tự ý bỏ việc mà không có lý do chính đáng từ ………………… liên tục trở lên.",ans:"05 ngày làm việc"},{id:"vb14-213",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 36",gt:"Với hợp đồng không xác định thời hạn: điều trị 12 tháng liên tục chưa hồi phục.",mn:'"Không xác định thời hạn: 12 tháng".',t:"f",q:"Theo Bộ Luật Lao động, người sử dụng lao động được đơn phương chấm dứt hợp đồng không xác định thời hạn khi người lao động bị ốm đau, tai nạn đã điều trị ………………… mà khả năng lao động chưa hồi phục.",ans:"12 tháng liên tục"},{id:"vb14-214",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 37",gt:"Không chấm dứt với người nuôi con dưới 12 tháng tuổi.",mn:'"Nuôi con dưới 12 tháng: được bảo vệ".',t:"f",q:"Theo Bộ Luật Lao động, người sử dụng lao động không được đơn phương chấm dứt hợp đồng lao động khi người lao động đang nuôi con dưới …………………",ans:"12 tháng tuổi"},{id:"vb14-215",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 40",gt:"Người lao động chấm dứt trái luật bồi thường nửa tháng tiền lương.",mn:'"NLĐ sai: nửa tháng lương".',t:"f",q:"Theo Bộ Luật Lao động, người lao động đơn phương chấm dứt hợp đồng lao động trái pháp luật phải bồi thường cho người sử dụng lao động ………………… theo hợp đồng lao động.",ans:"nửa tháng tiền lương"},{id:"vb14-216",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 41",gt:"Người sử dụng lao động trái luật trả thêm ít nhất 02 tháng tiền lương.",mn:'"NSDLĐ sai: ít nhất 2 tháng lương".',t:"f",q:"Theo Bộ Luật Lao động, khi đơn phương chấm dứt hợp đồng trái pháp luật và nhận lại người lao động, người sử dụng lao động phải trả thêm một khoản tiền ít nhất bằng ………………… theo hợp đồng lao động.",ans:"02 tháng tiền lương"},{id:"vb14-217",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 42",gt:"Thông báo trước 30 ngày cho Ủy ban nhân dân cấp tỉnh và người lao động.",mn:'"Thôi việc vì cơ cấu: 30 ngày".',t:"f",q:"Theo Bộ Luật Lao động, khi cho thôi việc do thay đổi cơ cấu, công nghệ hoặc vì lý do kinh tế, người sử dụng lao động phải thông báo trước ………………… cho Ủy ban nhân dân cấp tỉnh và cho người lao động.",ans:"30 ngày"},{id:"vb14-218",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 44",gt:"Thông báo công khai phương án trong 15 ngày kể từ ngày được thông qua.",mn:'"Phương án SDLĐ: công khai 15 ngày".',t:"f",q:"Theo Bộ Luật Lao động, phương án sử dụng lao động phải được thông báo công khai cho người lao động biết trong thời hạn ………………… kể từ ngày được thông qua.",ans:"15 ngày"},{id:"vb14-219",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 46",gt:"Trợ cấp thôi việc: mỗi năm một nửa tháng tiền lương.",mn:'"Thôi việc: mỗi năm nửa tháng".',t:"f",q:"Theo Bộ Luật Lao động, người sử dụng lao động trả trợ cấp thôi việc cho người lao động đã làm việc thường xuyên từ đủ 12 tháng trở lên, mỗi năm làm việc được trợ cấp …………………",ans:"một nửa tháng tiền lương"},{id:"vb14-220",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 46",gt:"Tính theo tiền lương bình quân 06 tháng liền kề trước khi thôi việc.",mn:'"Bình quân 6 tháng".',t:"f",q:"Theo Bộ Luật Lao động, tiền lương để tính trợ cấp thôi việc là tiền lương bình quân của ………………… theo hợp đồng lao động trước khi người lao động thôi việc.",ans:"06 tháng liền kề"},{id:"vb14-221",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 47",gt:"Trợ cấp mất việc làm ít nhất 02 tháng tiền lương.",mn:'"Mất việc: tối thiểu 2 tháng".',t:"f",q:"Theo Bộ Luật Lao động, trợ cấp mất việc làm được tính mỗi năm làm việc trả 01 tháng tiền lương nhưng ít nhất bằng …………………",ans:"02 tháng tiền lương"},{id:"vb14-222",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 48",gt:"Thanh toán trong 14 ngày làm việc kể từ ngày chấm dứt (một số trường hợp kéo dài không quá 30 ngày).",mn:'"Chấm dứt: 14 ngày làm việc".',t:"f",q:"Theo Bộ Luật Lao động, trong thời hạn ………………… kể từ ngày chấm dứt hợp đồng lao động, hai bên có trách nhiệm thanh toán đầy đủ các khoản tiền liên quan đến quyền lợi của mỗi bên.",ans:"14 ngày làm việc"},{id:"vb14-223",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 53",gt:"Thời hạn cho thuê lại lao động tối đa 12 tháng.",mn:'"Thuê lại: tối đa 12 tháng".',t:"f",q:"Theo Bộ Luật Lao động, thời hạn cho thuê lại lao động đối với người lao động tối đa là …………………",ans:"12 tháng"},{id:"vb14-224",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 61",gt:"Người học nghề, tập nghề phải đủ 14 tuổi trở lên.",mn:'"Học nghề: đủ 14 tuổi".',t:"f",q:"Theo Bộ Luật Lao động, người học nghề, người tập nghề để làm việc cho người sử dụng lao động phải ………………… trở lên và có đủ sức khỏe phù hợp (đối với nghề, công việc thông thường).",ans:"đủ 14 tuổi"},{id:"vb14-225",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 63",gt:"Đối thoại tại nơi làm việc phải tổ chức định kỳ ít nhất 01 năm một lần.",mn:'"Đối thoại: 1 năm/lần".',t:"f",q:"Theo Bộ Luật Lao động, người sử dụng lao động phải tổ chức đối thoại tại nơi làm việc định kỳ ít nhất ……………… một lần.",ans:"01 năm"},{id:"vb14-226",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 66",gt:"Nguyên tắc thương lượng tập thể gồm tự nguyện, hợp tác, thiện chí, bình đẳng, công khai và minh bạch.",mn:'"Công khai – minh bạch".',t:"f",q:"Theo Bộ Luật Lao động, thương lượng tập thể được tiến hành theo nguyên tắc tự nguyện, hợp tác, thiện chí, bình đẳng, ……………… và minh bạch.",ans:"công khai"},{id:"vb14-227",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 70",gt:"Thời gian bắt đầu thương lượng không được quá 30 ngày kể từ ngày nhận được yêu cầu.",mn:'"Bắt đầu thương lượng: 30 ngày".',t:"f",q:"Theo Bộ Luật Lao động, thời gian bắt đầu thương lượng tập thể không được quá ……………… kể từ ngày nhận được yêu cầu thương lượng tập thể.",ans:"30 ngày"},{id:"vb14-228",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 70",gt:"Thời gian thương lượng tập thể không được quá 90 ngày kể từ ngày bắt đầu, trừ khi các bên thỏa thuận khác.",mn:'"Thương lượng: 90 ngày".',t:"f",q:"Theo Bộ Luật Lao động, thời gian thương lượng tập thể không được quá ……………… kể từ ngày bắt đầu thương lượng, trừ trường hợp các bên có thỏa thuận khác.",ans:"90 ngày"},{id:"vb14-229",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 76",gt:"Thỏa ước lao động tập thể doanh nghiệp chỉ được ký khi có trên 50% người lao động tán thành.",mn:'"Trên 50% tán thành".',t:"f",q:"Theo Bộ Luật Lao động, thỏa ước lao động tập thể doanh nghiệp chỉ được ký kết khi có ……………… người lao động của doanh nghiệp biểu quyết tán thành.",ans:"trên 50%"},{id:"vb14-230",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 77",gt:"Người sử dụng lao động phải gửi thỏa ước trong thời hạn 10 ngày kể từ ngày ký kết.",mn:'"Gửi thỏa ước: 10 ngày".',t:"f",q:"Theo Bộ Luật Lao động, trong thời hạn ……………… kể từ ngày thỏa ước lao động tập thể được ký kết, người sử dụng lao động phải gửi 01 bản đến cơ quan chuyên môn về lao động thuộc Ủy ban nhân dân cấp tỉnh.",ans:"10 ngày"},{id:"vb14-231",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 89",gt:"Chi phí thỏa ước lao động tập thể do người sử dụng lao động chi trả.",mn:'"Chủ trả chi phí thỏa ước".',t:"f",q:"Theo Bộ Luật Lao động, mọi chi phí cho việc thương lượng, ký kết, sửa đổi, bổ sung, gửi và công bố thỏa ước lao động tập thể do phía ……………… chi trả.",ans:"người sử dụng lao động"},{id:"vb14-232",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 90",gt:"Mức lương theo công việc hoặc chức danh không được thấp hơn mức lương tối thiểu.",mn:'"Lương công việc ≥ tối thiểu".',t:"f",q:"Theo Bộ Luật Lao động, mức lương theo công việc hoặc chức danh không được ……………… mức lương tối thiểu.",ans:"thấp hơn"},{id:"vb14-233",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 91",gt:"Mức lương tối thiểu được xác lập theo vùng, ấn định theo tháng, giờ.",mn:'"Theo vùng – ấn định tháng, giờ".',t:"f",q:"Theo Bộ Luật Lao động, mức lương tối thiểu được xác lập theo vùng, ấn định theo ……………… và giờ.",ans:"tháng"},{id:"vb14-234",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 98",gt:"Làm thêm giờ ngày thường được trả ít nhất bằng 150%.",mn:'"Ngày thường: ≥150%".',t:"f",q:"Theo Bộ Luật Lao động, người lao động làm thêm giờ vào ngày thường được trả lương ít nhất bằng ……………… theo đơn giá tiền lương hoặc tiền lương thực trả.",ans:"150%"},{id:"vb14-235",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 98",gt:"Làm thêm giờ ngày nghỉ hằng tuần được trả ít nhất bằng 200%.",mn:'"Nghỉ tuần: ≥200%".',t:"f",q:"Theo Bộ Luật Lao động, người lao động làm thêm giờ vào ngày nghỉ hằng tuần được trả lương ít nhất bằng ……………….",ans:"200%"},{id:"vb14-236",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 98",gt:"Làm việc ban đêm được trả thêm ít nhất bằng 30% tiền lương của công việc ngày làm việc bình thường.",mn:'"Ban đêm: thêm ≥30%".',t:"f",q:"Theo Bộ Luật Lao động, người lao động làm việc vào ban đêm được trả thêm ít nhất bằng ……………… tiền lương của công việc ngày làm việc bình thường.",ans:"30%"},{id:"vb14-237",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 102",gt:"Mức khấu trừ tiền lương hằng tháng không được quá 30% tiền lương thực trả sau khi trích nộp các khoản bắt buộc.",mn:'"Khấu trừ: ≤30%/tháng".',t:"f",q:"Theo Bộ Luật Lao động, mức khấu trừ tiền lương hằng tháng không được quá ……………… tiền lương thực trả hằng tháng của người lao động sau khi trích nộp bảo hiểm bắt buộc và thuế thu nhập cá nhân.",ans:"30%"},{id:"vb14-238",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 97",gt:"Vì lý do bất khả kháng, việc trả lương chậm không được quá 30 ngày.",mn:'"Chậm lương tối đa: 30 ngày".',t:"f",q:"Theo Bộ Luật Lao động, trường hợp vì lý do bất khả kháng, việc trả lương chậm không được quá ……………….",ans:"30 ngày"},{id:"vb14-239",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 99",gt:"Ngừng việc do lỗi của người sử dụng lao động thì người lao động được trả đủ tiền lương theo hợp đồng.",mn:'"Lỗi chủ: trả đủ lương".',t:"f",q:"Theo Bộ Luật Lao động, trường hợp ngừng việc do lỗi của người sử dụng lao động thì người lao động được trả ……………… tiền lương theo hợp đồng lao động.",ans:"đủ"},{id:"vb14-240",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 105",gt:"Thời giờ làm việc bình thường không quá 08 giờ/ngày và không quá 48 giờ/tuần.",mn:'"Bình thường: 8 giờ/ngày".',t:"f",q:"Theo Bộ Luật Lao động, thời giờ làm việc bình thường không quá ……………… trong 01 ngày và không quá 48 giờ trong 01 tuần.",ans:"08 giờ"},{id:"vb14-241",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 106",gt:"Giờ làm việc ban đêm được tính từ 22 giờ đến 06 giờ sáng ngày hôm sau.",mn:'"Ban đêm: từ 22h".',t:"f",q:"Theo Bộ Luật Lao động, giờ làm việc ban đêm được tính từ ……………… đến 06 giờ sáng ngày hôm sau.",ans:"22 giờ"},{id:"vb14-242",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 107",gt:"Số giờ làm thêm bảo đảm không quá 40 giờ trong 01 tháng.",mn:'"Làm thêm: ≤40 giờ/tháng".',t:"f",q:"Theo Bộ Luật Lao động, số giờ làm thêm của người lao động phải bảo đảm không quá ……………… trong 01 tháng.",ans:"40 giờ"},{id:"vb14-243",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 107",gt:"Số giờ làm thêm bảo đảm không quá 200 giờ trong 01 năm, trừ trường hợp đặc biệt được làm không quá 300 giờ.",mn:'"Làm thêm: ≤200 giờ/năm".',t:"f",q:"Theo Bộ Luật Lao động, số giờ làm thêm của người lao động bảo đảm không quá ……………… trong 01 năm, trừ một số ngành, nghề, công việc đặc biệt.",ans:"200 giờ"},{id:"vb14-244",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 110",gt:"Người lao động làm theo ca được nghỉ ít nhất 12 giờ trước khi chuyển ca.",mn:'"Chuyển ca: ≥12 giờ".',t:"f",q:"Theo Bộ Luật Lao động, người lao động làm việc theo ca được nghỉ ít nhất ……………… trước khi chuyển sang ca làm việc khác.",ans:"12 giờ"},{id:"vb14-245",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 111",gt:"Mỗi tuần người lao động được nghỉ ít nhất 24 giờ liên tục.",mn:'"Nghỉ tuần: ≥24 giờ".',t:"f",q:"Theo Bộ Luật Lao động, mỗi tuần người lao động được nghỉ hằng tuần ít nhất ……………… liên tục.",ans:"24 giờ"},{id:"vb14-246",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 112",gt:"Dịp Tết Âm lịch người lao động được nghỉ 05 ngày hưởng nguyên lương.",mn:'"Tết Âm lịch: 5 ngày".',t:"f",q:"Theo Bộ Luật Lao động, dịp Tết Âm lịch người lao động được nghỉ làm việc, hưởng nguyên lương ……………….",ans:"05 ngày"},{id:"vb14-247",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 113",gt:"Điều kiện bình thường được nghỉ hằng năm 12 ngày làm việc.",mn:'"Nghỉ hằng năm: 12 ngày".',t:"f",q:"Theo Bộ Luật Lao động, người lao động làm việc đủ 12 tháng trong điều kiện bình thường được nghỉ hằng năm hưởng nguyên lương ……………… làm việc.",ans:"12 ngày"},{id:"vb14-248",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 114",gt:"Cứ đủ 05 năm làm việc thì số ngày nghỉ hằng năm được tăng thêm 01 ngày.",mn:'"Thâm niên: 5 năm thêm 1 ngày".',t:"f",q:"Theo Bộ Luật Lao động, cứ đủ ……………… làm việc cho một người sử dụng lao động thì số ngày nghỉ hằng năm được tăng thêm tương ứng 01 ngày.",ans:"05 năm"},{id:"vb14-249",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 118",gt:"Sử dụng từ 10 người lao động trở lên thì nội quy lao động phải bằng văn bản.",mn:'"Từ 10 lao động: văn bản".',t:"f",q:"Theo Bộ Luật Lao động, người sử dụng lao động sử dụng từ ……………… người lao động trở lên thì nội quy lao động phải bằng văn bản.",ans:"10"},{id:"vb14-250",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 121",gt:"Nội quy lao động có hiệu lực sau 15 ngày kể từ ngày nhận đủ hồ sơ đăng ký.",mn:'"Nội quy: hiệu lực 15 ngày".',t:"f",q:"Theo Bộ Luật Lao động, nội quy lao động có hiệu lực sau ……………… kể từ ngày cơ quan nhà nước có thẩm quyền nhận được đầy đủ hồ sơ đăng ký nội quy lao động.",ans:"15 ngày"},{id:"vb14-251",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 123",gt:"Thời hiệu xử lý kỷ luật lao động thông thường là 06 tháng kể từ ngày xảy ra hành vi vi phạm.",mn:'"Thời hiệu: 6 tháng".',t:"f",q:"Theo Bộ Luật Lao động, thời hiệu xử lý kỷ luật lao động thông thường là ……………… kể từ ngày xảy ra hành vi vi phạm.",ans:"06 tháng"},{id:"vb14-252",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 123",gt:"Hành vi liên quan tài chính, tài sản, bí mật công nghệ, kinh doanh thì thời hiệu là 12 tháng.",mn:'"Tài chính/bí mật: 12 tháng".',t:"f",q:"Theo Bộ Luật Lao động, hành vi vi phạm liên quan trực tiếp đến tài chính, tài sản, tiết lộ bí mật công nghệ, bí mật kinh doanh thì thời hiệu xử lý kỷ luật lao động là ……………….",ans:"12 tháng"},{id:"vb14-253",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 124",gt:"Kỷ luật kéo dài thời hạn nâng lương không quá 06 tháng.",mn:'"Kéo dài nâng lương: ≤6 tháng".',t:"f",q:"Theo Bộ Luật Lao động, hình thức kỷ luật kéo dài thời hạn nâng lương được áp dụng với thời hạn không quá ……………….",ans:"06 tháng"},{id:"vb14-254",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 125",gt:"Sa thải khi tự ý bỏ việc 05 ngày/30 ngày hoặc 20 ngày cộng dồn trong 365 ngày không có lý do chính đáng.",mn:'"5/30 ngày hoặc 20/365 ngày".',t:"f",q:"Theo Bộ Luật Lao động, hình thức sa thải được áp dụng khi người lao động tự ý bỏ việc 05 ngày cộng dồn trong thời hạn 30 ngày hoặc ……………… cộng dồn trong thời hạn 365 ngày mà không có lý do chính đáng.",ans:"20 ngày"},{id:"vb14-255",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 128",gt:"Tạm đình chỉ công việc thông thường không quá 15 ngày, đặc biệt không quá 90 ngày.",mn:'"Đặc biệt: ≤90 ngày".',t:"f",q:"Theo Bộ Luật Lao động, thời hạn tạm đình chỉ công việc thông thường không được quá 15 ngày, trường hợp đặc biệt không được quá ……………….",ans:"90 ngày"},{id:"vb14-256",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 128",gt:"Trong thời gian tạm đình chỉ, người lao động được tạm ứng 50% tiền lương trước khi bị đình chỉ.",mn:'"Tạm ứng: 50% lương".',t:"f",q:"Theo Bộ Luật Lao động, trong thời gian bị tạm đình chỉ công việc, người lao động được tạm ứng ……………… tiền lương trước khi bị đình chỉ công việc.",ans:"50%"},{id:"vb14-257",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 133",gt:"Chính phủ quyết định Chương trình quốc gia về an toàn, vệ sinh lao động.",mn:'"Quốc gia: Chính phủ quyết định".',t:"f",q:"Theo Bộ Luật Lao động, ……………… quyết định Chương trình quốc gia về an toàn, vệ sinh lao động.",ans:"Chính phủ"},{id:"vb14-258",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 133",gt:"Ủy ban nhân dân cấp tỉnh trình Hội đồng nhân dân cùng cấp quyết định chương trình ATVSLĐ của địa phương.",mn:'"Địa phương: UBND cấp tỉnh trình HĐND".',t:"f",q:"Theo Bộ Luật Lao động, ở địa phương, ……………… trình Hội đồng nhân dân cùng cấp quyết định Chương trình an toàn, vệ sinh lao động của địa phương.",ans:"Ủy ban nhân dân cấp tỉnh"},{id:"vb14-259",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 132",gt:"Các chủ thể liên quan phải thực hiện quy định của pháp luật về an toàn, vệ sinh lao động.",mn:'"Tuân thủ pháp luật ATVSLĐ".',t:"f",q:"Theo Bộ Luật Lao động, người sử dụng lao động, người lao động và cơ quan, tổ chức, cá nhân có liên quan phải thực hiện quy định của pháp luật về ……………….",ans:"an toàn, vệ sinh lao động"},{id:"vb14-260",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 139",gt:"Nghỉ thai sản trước và sau sinh là 06 tháng.",mn:'"Thai sản 6 tháng".',t:"f",q:"Theo Bộ Luật Lao động, lao động nữ được nghỉ thai sản trước và sau khi sinh con trong điều kiện thông thường là ……………………",ans:"06 tháng"},{id:"vb14-261",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 139",gt:"Thời gian nghỉ trước khi sinh không quá 02 tháng.",mn:'"Trước sinh ≤ 2 tháng".',t:"f",q:"Theo Bộ Luật Lao động, trong chế độ nghỉ thai sản, thời gian nghỉ trước khi sinh không quá ……………………",ans:"02 tháng"},{id:"vb14-262",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 137",gt:"Thời gian hành kinh được nghỉ 30 phút/ngày.",mn:'"Hành kinh nghỉ 30 phút".',t:"f",q:"Theo Bộ Luật Lao động, trong thời gian hành kinh, lao động nữ được nghỉ mỗi ngày …………………… trong thời gian làm việc mà vẫn hưởng đủ lương.",ans:"30 phút"},{id:"vb14-263",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 137",gt:"Nuôi con dưới 12 tháng tuổi được nghỉ 60 phút/ngày.",mn:'"Nuôi con nhỏ nghỉ 60 phút".',t:"f",q:"Theo Bộ Luật Lao động, trong thời gian nuôi con dưới 12 tháng tuổi, lao động nữ được nghỉ mỗi ngày …………………… trong thời gian làm việc.",ans:"60 phút"},{id:"vb14-264",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 137",gt:"Mốc bảo vệ thai sản là mang thai từ tháng thứ 07.",mn:'"Tháng thứ 7".',t:"f",q:"Theo Bộ Luật Lao động, người sử dụng lao động không được sử dụng lao động nữ làm việc ban đêm, làm thêm giờ, đi công tác xa khi mang thai từ tháng thứ …………………… (trong điều kiện làm việc bình thường).",ans:"07"},{id:"vb14-265",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 137",gt:"Ở vùng khó khăn, mốc sớm hơn: mang thai từ tháng thứ 06.",mn:'"Vùng khó khăn: tháng thứ 6".',t:"f",q:"Theo Bộ Luật Lao động, đối với lao động nữ làm việc ở vùng cao, vùng sâu, vùng xa, biên giới, hải đảo, mốc bảo vệ nêu trên được áp dụng khi mang thai từ tháng thứ ……………………",ans:"06"},{id:"vb14-266",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 143",gt:"Lao động chưa thành niên là người chưa đủ 18 tuổi.",mn:'"Chưa đủ 18".',t:"f",q:"Theo Bộ Luật Lao động, lao động chưa thành niên là người lao động chưa đủ ……………………",ans:"18 tuổi"},{id:"vb14-267",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 143",gt:"Người từ đủ 13 đến chưa đủ 15 tuổi chỉ được làm công việc nhẹ theo danh mục.",mn:'"13–15: công việc nhẹ".',t:"f",q:"Theo Bộ Luật Lao động, người từ đủ 13 tuổi đến chưa đủ 15 tuổi chỉ được làm …………………… theo danh mục do Bộ trưởng Bộ Lao động - Thương binh và Xã hội ban hành.",ans:"công việc nhẹ"},{id:"vb14-268",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 146",gt:"Người chưa đủ 15 tuổi làm không quá 04 giờ/ngày.",mn:'"Chưa đủ 15: 4 giờ/ngày".',t:"f",q:"Theo Bộ Luật Lao động, thời giờ làm việc của người chưa đủ 15 tuổi không được quá …………………… trong 01 ngày.",ans:"04 giờ"},{id:"vb14-269",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 146",gt:"Người chưa đủ 15 tuổi làm không quá 20 giờ/tuần.",mn:'"Chưa đủ 15: 20 giờ/tuần".',t:"f",q:"Theo Bộ Luật Lao động, thời giờ làm việc của người chưa đủ 15 tuổi không được quá …………………… trong 01 tuần.",ans:"20 giờ"},{id:"vb14-270",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 146",gt:"Người từ đủ 15 đến chưa đủ 18 tuổi làm không quá 08 giờ/ngày (và 40 giờ/tuần).",mn:'"15–18: 8 giờ/ngày".',t:"f",q:"Theo Bộ Luật Lao động, thời giờ làm việc của người từ đủ 15 tuổi đến chưa đủ 18 tuổi không được quá …………………… trong 01 ngày.",ans:"08 giờ"},{id:"vb14-271",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 145",gt:"Kiểm tra sức khỏe định kỳ ít nhất một lần trong 06 tháng.",mn:'"Khám 6 tháng/lần".',t:"f",q:"Theo Bộ Luật Lao động, khi sử dụng người chưa đủ 15 tuổi, người sử dụng lao động phải tổ chức kiểm tra sức khỏe định kỳ ít nhất một lần trong ……………………",ans:"06 tháng"},{id:"vb14-272",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 151",gt:"Điều kiện: đủ 18 tuổi trở lên, năng lực hành vi dân sự đầy đủ, có giấy phép lao động.",mn:'"Lao động nước ngoài đủ 18".',t:"f",q:"Theo Bộ Luật Lao động, người lao động nước ngoài làm việc tại Việt Nam phải có độ tuổi đủ …………………… trở lên và có năng lực hành vi dân sự đầy đủ.",ans:"18 tuổi"},{id:"vb14-273",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 155",gt:"Giấy phép lao động tối đa 02 năm.",mn:'"Giấy phép tối đa 2 năm".',t:"f",q:"Theo Bộ Luật Lao động, thời hạn của giấy phép lao động cấp cho người lao động nước ngoài tối đa là ……………………",ans:"02 năm"},{id:"vb14-274",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 155",gt:"Chỉ được gia hạn một lần, thời hạn tối đa 02 năm.",mn:'"Gia hạn 1 lần duy nhất".',t:"f",q:"Theo Bộ Luật Lao động, trường hợp gia hạn giấy phép lao động thì chỉ được gia hạn …………………… với thời hạn tối đa là 02 năm.",ans:"một lần"},{id:"vb14-275",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 160",gt:"Ngưỡng suy giảm khả năng lao động là từ 51% trở lên.",mn:'"Từ 51% trở lên".',t:"f",q:"Theo Bộ Luật Lao động, cấm sử dụng người lao động là người khuyết tật nhẹ suy giảm khả năng lao động từ …………………… trở lên làm thêm giờ, làm việc ban đêm, trừ trường hợp họ đồng ý.",ans:"51%"},{id:"vb14-276",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 162",gt:"Giúp việc gia đình: đơn phương chấm dứt phải báo trước ít nhất 15 ngày.",mn:'"Giúp việc báo trước 15 ngày".',t:"f",q:"Theo Bộ Luật Lao động, đối với lao động là người giúp việc gia đình, một bên có quyền đơn phương chấm dứt hợp đồng lao động bất kỳ khi nào nhưng phải báo trước ít nhất ……………………",ans:"15 ngày"},{id:"vb14-277",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 169",gt:"Lao động nam nghỉ hưu ở đủ 62 tuổi vào năm 2028.",mn:'"Nam 62 (2028)".',t:"f",q:"Theo Bộ Luật Lao động, lộ trình tuổi nghỉ hưu trong điều kiện lao động bình thường hướng đến mức đủ …………………… đối với lao động nam vào năm 2028.",ans:"62 tuổi"},{id:"vb14-278",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 169",gt:"Lao động nữ nghỉ hưu ở đủ 60 tuổi vào năm 2035.",mn:'"Nữ 60 (2035)".',t:"f",q:"Theo Bộ Luật Lao động, lộ trình tuổi nghỉ hưu trong điều kiện lao động bình thường hướng đến mức đủ 60 tuổi đối với lao động nữ vào năm ……………………",ans:"2035"},{id:"vb14-279",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 169",gt:"Được nghỉ hưu sớm nhưng không quá 05 tuổi so với tuổi nghỉ hưu bình thường.",mn:'"Sớm không quá 5 tuổi".',t:"f",q:"Theo Bộ Luật Lao động, người lao động bị suy giảm khả năng lao động hoặc làm nghề đặc biệt nặng nhọc, độc hại, nguy hiểm có thể nghỉ hưu ở tuổi thấp hơn nhưng không quá …………………… so với quy định trong điều kiện bình thường.",ans:"05 tuổi"},{id:"vb14-280",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 184",gt:"Hòa giải viên lao động do Chủ tịch Ủy ban nhân dân cấp tỉnh bổ nhiệm.",mn:'"Chủ tịch UBND tỉnh bổ nhiệm".',t:"f",q:"Theo Bộ Luật Lao động, hòa giải viên lao động do …………………… bổ nhiệm để hòa giải tranh chấp lao động.",ans:"Chủ tịch Ủy ban nhân dân cấp tỉnh"},{id:"vb14-281",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 185",gt:"Nhiệm kỳ Hội đồng trọng tài lao động là 05 năm.",mn:'"Nhiệm kỳ 5 năm".',t:"f",q:"Theo Bộ Luật Lao động, nhiệm kỳ của Hội đồng trọng tài lao động là ……………………",ans:"05 năm"},{id:"vb14-282",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 185",gt:"Hội đồng trọng tài lao động có ít nhất 15 người.",mn:'"Ít nhất 15 người".',t:"f",q:"Theo Bộ Luật Lao động, số lượng trọng tài viên lao động của Hội đồng trọng tài lao động do Chủ tịch Ủy ban nhân dân cấp tỉnh quyết định, ít nhất là ……………………",ans:"15 người"},{id:"vb14-283",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 190",gt:"Thời hiệu yêu cầu hòa giải viên hòa giải là 06 tháng kể từ ngày phát hiện hành vi vi phạm.",mn:'"Hòa giải viên: 6 tháng".',t:"f",q:"Theo Bộ Luật Lao động, thời hiệu yêu cầu hòa giải viên lao động thực hiện hòa giải tranh chấp lao động cá nhân là ……………………",ans:"06 tháng"},{id:"vb14-284",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 190",gt:"Thời hiệu yêu cầu Tòa án là 01 năm kể từ ngày phát hiện hành vi vi phạm.",mn:'"Tòa án: 1 năm".',t:"f",q:"Theo Bộ Luật Lao động, thời hiệu yêu cầu Tòa án giải quyết tranh chấp lao động cá nhân là ……………………",ans:"01 năm"},{id:"vb14-285",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 202",gt:"Ra quyết định đình công khi có trên 50% số người được lấy ý kiến đồng ý.",mn:'"Quá bán 50%".',t:"f",q:"Theo Bộ Luật Lao động, tổ chức đại diện người lao động ra quyết định đình công bằng văn bản khi có trên …………………… số người được lấy ý kiến đồng ý.",ans:"50%"},{id:"vb14-286",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 202",gt:"Phải gửi văn bản ít nhất 05 ngày làm việc trước ngày bắt đầu đình công.",mn:'"Báo trước 5 ngày làm việc".',t:"f",q:"Theo Bộ Luật Lao động, tổ chức đại diện người lao động phải gửi văn bản quyết định đình công cho người sử dụng lao động và cơ quan liên quan ít nhất …………………… trước ngày bắt đầu đình công.",ans:"05 ngày làm việc"},{id:"vb14-287",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 198",gt:"Đình công là ngừng việc tạm thời, tự nguyện và có tổ chức.",mn:'"Tạm thời – tự nguyện – có tổ chức".',t:"f",q:"Theo Bộ Luật Lao động, đình công là sự ngừng việc …………………… của người lao động nhằm đạt được yêu cầu trong quá trình giải quyết tranh chấp lao động.",ans:"tạm thời, tự nguyện và có tổ chức"},{id:"vb14-288",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 218",gt:"Dùng dưới 10 lao động được miễn, giảm một số thủ tục.",mn:'"Dưới 10 lao động".',t:"f",q:"Theo Bộ Luật Lao động, người sử dụng lao động sử dụng dưới …………………… người lao động thì được miễn, giảm một số thủ tục theo quy định của Chính phủ.",ans:"10"},{id:"vb14-289",s:"PHẦN III. CÂU ĐIỀN KHUYẾT",cc:"Bộ Luật Lao động (VBHN 18/VBHN-VPQH), Điều 220",gt:"Bộ luật này có hiệu lực từ ngày 01/01/2021.",mn:'"Hiệu lực 01/01/2021".',t:"f",q:"Theo Bộ Luật Lao động, Bộ luật này có hiệu lực thi hành từ ngày ……………………",ans:"01 tháng 01 năm 2021"}];export{n as default};
